/* Student's Book va Workbook audiolari: audio/a2/student, audio/a2/workbook.
   Dars: { id, u, book, title, dur (soniya), audio, lines: [[kim, inglizcha, oʻzbekcha, soniya], ...], q (ixtiyoriy): [{ t, o, a, why }] }
   Matnlar audiodan avtomatik chiqarilgan (xato boʻlishi mumkin). Savollar (q) va oʻzbekcha tarjima hozircha 1–6-unitlarda bor;
   qolganlarida q yoʻq — sahifa ularni savolsiz koʻrsatadi. q qoʻshilsa, sahifa oʻzi savollarni chiqaradi. */
var AUDIO_LESSONS = [
{"id":"sb-01","u":1,"book":"Student's Book","title":"Daily Routines and Habits","dur":131,"audio":"audio/a2/student/unit-01.mp3","lines":[["Interviewer","Good morning. I'm doing a survey about people's daily routines. Could I ask you a few questions?","Xayrli tong. Men odamlarning kundalik tartibi boʻyicha soʻrovnoma oʻtkazyapman. Bir nechta savol bersam boʻladimi?",5.4],["Sophie","Sure.","Albatta.",11.5],["Interviewer","Great. First, can I have your name?","Zoʻr. Avval ismingizni aytsangiz.",13.3],["Sophie","Yes, it's Sophie Carter.","Ha, men Sophie Carter.",17.5],["Interviewer","Could you spell your surname, please?","Familiyangizni harflab bera olasizmi?",19.7],["Sophie","Sure. It's C-A-R-T-E-R.","Albatta. C-A-R-T-E-R.",23.5],["Interviewer","Thank you. Now, let's talk about your mornings. What time do you usually get up?","Rahmat. Endi ertalablaringiz haqida gaplashaylik. Odatda soat nechada turasiz?",27.9],["Sophie","Quite early. My alarm goes off at 6, but I don't get up immediately. I usually stay in bed for another 15 minutes, so I get up at 6.15. Then I have a shower and get dressed.","Ancha erta. Budilnik 6 da chaladi, lekin darrov turmayman. Odatda yana 15 daqiqa yotaman, shuning uchun 6.15 da turaman. Keyin dushga tushaman va kiyinaman.",34],["Interviewer","Do you have breakfast at home?","Nonushtani uyda qilasizmi?",48],["Sophie","Yes, always. I usually have some cereal and a banana. I used to drink coffee in the morning, but these days I prefer tea.","Ha, doim. Odatda bir oz quruq nonushta (kornfleks) va banan yeyman. Ilgari ertalab kofe ichardim, hozir esa choyni afzal koʻraman.",51],["Interviewer","And what time do you leave home?","Uydan soat nechada chiqasiz?",60.2],["Sophie","At about 7.20. I work at a bookshop in the town centre, and I normally go there by bus.","Taxminan 7.20 da. Men shahar markazidagi kitob doʻkonida ishlayman, odatda avtobusda boraman.",62.5],["Interviewer","Is it a long journey?","Yoʻl uzoqmi?",69.7],["Sophie","Not really. It usually takes about 30 minutes. I sometimes listen to music on the bus, but I often just look out of the window.","Unchalik emas. Odatda taxminan 30 daqiqa ketadi. Baʼzan avtobusda musiqa tinglayman, lekin koʻpincha oynadan tashqariga qarab ketaman.",72],["Interviewer","What happens after work?","Ishdan keyin nima qilasiz?",81.1],["Sophie","I finish at half past four. On Tuesdays, I go swimming at the sports centre. I swim for about an hour, so I normally get home just after six.","Soat toʻrt yarimda tugataman. Seshanba kunlari sport markazida suzishga boraman. Taxminan bir soat suzaman, shuning uchun uyga odatda oltidan sal oʻtib qaytaman.",83.5],["Interviewer","What do you do in the evening?","Kechqurun nima qilasiz?",93],["Sophie","I make dinner first. I really enjoy cooking, especially pasta and soup. After dinner, I usually watch TV or talk to my friends online.","Avval kechki ovqat tayyorlayman. Ovqat pishirishni juda yaxshi koʻraman, ayniqsa pasta va shoʻrva. Ovqatdan keyin odatda televizor koʻraman yoki doʻstlarim bilan onlayn gaplashaman.",96.1],["Interviewer","And what time do you normally go to bed?","Odatda soat nechada uxlaysiz?",107],["Sophie","Around 10.45. Before I sleep, I usually read for about 20 minutes. It helps me relax.","Taxminan 10.45 da. Uxlashdan oldin odatda 20 daqiqa kitob oʻqiyman. Bu dam olishimga yordam beradi.",110.5],["Interviewer","One last question. Are weekends different?","Oxirgi savol. Dam olish kunlari boshqachami?",118.5],["Sophie","Very different. On Saturdays, I don't use an alarm. I usually wake up around nine and meet my friends for breakfast.","Juda boshqacha. Shanba kunlari budilnik qoʻymayman. Odatda toʻqqizlarda uygʻonaman va doʻstlarim bilan nonushta qilish uchun uchrashaman.",122.2]],"q":[{"t":"What time does Sophie get up?","o":["6:00","6:15","7:20"],"a":1,"why":"Budilnik 6 da chaladi, u 15 daqiqadan keyin, 6.15 da turadi."},{"t":"What does Sophie usually have for breakfast?","o":["Toast and tea","Cereal and a banana","Only coffee"],"a":1},{"t":"How does Sophie get to work?","o":["By bus","By car","On foot"],"a":0},{"t":"What does Sophie do on Tuesdays after work?","o":["She plays tennis","She cooks for friends","She goes swimming"],"a":2},{"t":"What is different about Saturdays?","o":["She works at the bookshop","She doesn't use an alarm","She goes to bed early"],"a":1,"why":"On Saturdays, I don't use an alarm."}]},
{"id":"sb-02","u":2,"book":"Student's Book","title":"Family, Friends and Relationships","dur":131,"audio":"audio/a2/student/unit-02.mp3","lines":[["Interviewer","Hi, I'm collecting information for a class project about families and friendships. Can I ask you a few questions?","Salom, men oila va doʻstlik haqidagi sinf loyihasi uchun maʼlumot yigʻyapman. Bir nechta savol bersam boʻladimi?",6],["Lucy","Sure, that sounds interesting.","Albatta, qiziq ekan.",13.8],["Interviewer","Great! First, could you tell me your name?","Zoʻr! Avval ismingizni aytsangiz.",16.6],["Lucy","My name's Lucy Bennett.","Ismim Lucy Bennett.",20.6],["Interviewer","Could you spell your surname, please?","Familiyangizni harflab bera olasizmi?",23.3],["Lucy","Yes, it's B-E-N-N-E-T-T.","Ha, B-E-N-N-E-T-T.",25.1],["Interviewer","Thanks. So, Lucy, do you have a big family?","Rahmat. Xoʻsh, Lucy, oilangiz kattami?",32.6],["Lucy","Not really. There are four people in my family. My parents, my younger brother and me. My brother's name is Jack. He's 15, so he's three years younger than I am.","Unchalik emas. Oilamizda toʻrt kishi: ota-onam, kichik ukam va men. Ukamning ismi Jack. U 15 yoshda, demak mendan uch yosh kichik.",37.5],["Interviewer","Do you spend much time together?","Birga koʻp vaqt oʻtkazasizlarmi?",50.2],["Lucy","Yes, especially at weekends. Jack and I sometimes argue about small things, but we're actually quite close. We both love films, so we usually watch one together on Friday evenings.","Ha, ayniqsa dam olish kunlari. Jack bilan baʼzan mayda narsalar uchun tortishamiz, lekin aslida juda yaqinmiz. Ikkimiz ham kinoni yaxshi koʻramiz, shuning uchun odatda juma kechqurunlari birga film koʻramiz.",52.6],["Interviewer","What about your parents?","Ota-onangiz-chi?",66.2],["Lucy","My mum works at a hospital, and my dad is a bus driver. They're both busy during the week. We always try to have dinner together at about 7.30.","Onam kasalxonada ishlaydi, dadam avtobus haydovchisi. Ikkalasi ham hafta davomida band. Biz doim soat 7.30 atrofida birga kechki ovqat yeyishga harakat qilamiz.",68.6],["Interviewer","Do any other relatives live near you?","Yaqin atrofda boshqa qarindoshlaringiz yashaydimi?",79.1],["Lucy","My grandmother does. She lives about 10 minutes away, so I visit her every Wednesday after college. We usually have tea and talk for an hour or two.","Buvim yashaydi. U taxminan 10 daqiqalik masofada yashaydi, shuning uchun har chorshanba kollejdan keyin uning oldiga boraman. Odatda choy ichib, bir-ikki soat gaplashamiz.",82.1],["Interviewer","And what about your friends? Who are you closest to?","Doʻstlaringiz-chi? Kim bilan eng yaqinsiz?",92.4],["Lucy","My best friend is Emma. We met at primary school when we were seven. She's friendly and really funny. We don't study at the same college now, but we still see each other regularly.","Eng yaqin doʻstim Emma. Biz yetti yoshimizda boshlangʻich maktabda tanishganmiz. U xushmuomala va juda quvnoq. Hozir bir kollejda oʻqimaymiz, lekin hamon muntazam koʻrishib turamiz.",96.5],["Interviewer","When do you normally meet?","Odatda qachon uchrashasizlar?",108.8],["Lucy","Usually on Saturdays. We often go shopping or meet at a café called Corner. Sometimes we just walk around town and talk.","Odatda shanba kunlari. Koʻpincha xarid qilgani boramiz yoki Corner nomli kafeda uchrashamiz. Baʼzan shunchaki shaharda aylanib gaplashamiz.",110.1],["Interviewer","How often do you speak during the week?","Hafta davomida qanchalik tez-tez gaplashasizlar?",120.6],["Lucy","Almost every day. We usually send messages, and we have a longer phone call on Thursday evenings.","Deyarli har kuni. Odatda xabar yozishamiz, payshanba kechqurunlari esa uzoqroq telefonda gaplashamiz.",123.8]],"q":[{"t":"How old is Lucy's brother?","o":["12","15","18"],"a":1,"why":"Jack 15 yoshda, Lucy'dan uch yosh kichik."},{"t":"What do Lucy and Jack usually do on Friday evenings?","o":["They go shopping.","They have dinner with their grandmother.","They watch a film."],"a":2},{"t":"What does Lucy's father do?","o":["He is a bus driver.","He works at a hospital.","He is a teacher."],"a":0},{"t":"When does Lucy visit her grandmother?","o":["On Saturdays","On Wednesdays","On Thursdays"],"a":1},{"t":"When do Lucy and Emma have a longer phone call?","o":["On Thursday evenings","On Friday evenings","On Saturday mornings"],"a":0}]},
{"id":"sb-03","u":3,"book":"Student's Book","title":"Hobbies and free time","dur":123,"audio":"audio/a2/student/unit-03.mp3","lines":[["Interviewer","Hi. I'm doing a survey about how people spend their free time. Could I ask you a few questions?","Salom. Men odamlar boʻsh vaqtini qanday oʻtkazishi boʻyicha soʻrovnoma oʻtkazyapman. Bir nechta savol bersam boʻladimi?",4.5],["Anna","Of course.","Albatta.",11.6],["Interviewer","Great. First, what's your name?","Zoʻr. Avval ismingiz nima?",13.2],["Anna","My name's Anna Wilson.","Ismim Anna Wilson.",16.4],["Interviewer","Could you spell your surname for me?","Familiyangizni harflab bera olasizmi?",19.1],["Anna","Sure. It's W-I-L-S-O-N.","Albatta. W-I-L-S-O-N.",21.8],["Interviewer","Thanks. So, Anna, what do you like doing in your free time?","Rahmat. Xoʻsh, Anna, boʻsh vaqtingizda nima qilishni yoqtirasiz?",27.4],["Anna","I have several hobbies, but my favourite is photography. I started about two years ago when my parents gave me a camera for my birthday. I usually take pictures of buildings, streets and people.","Mening bir nechta xobbim bor, lekin eng yaxshi koʻrganim fotografiya. Taxminan ikki yil oldin tugʻilgan kunimga ota-onam menga kamera sovgʻa qilganda boshlaganman. Odatda binolar, koʻchalar va odamlarni suratga olaman.",32.8],["Interviewer","When do you normally have time for photography?","Fotografiya uchun odatda qachon vaqtingiz boʻladi?",46.6],["Anna","Mostly at the weekend. On Saturday mornings, I usually walk around the town centre with my camera. I sometimes spend two or three hours outside if the weather is nice.","Asosan dam olish kunlari. Shanba kuni ertalab odatda kamera bilan shahar markazida aylanaman. Ob-havo yaxshi boʻlsa, baʼzan tashqarida ikki-uch soat oʻtkazaman.",49.9],["Interviewer","Do you prefer doing things outside?","Tashqarida shugʻullanishni afzal koʻrasizmi?",61.3],["Anna","Not always. During the week, I often stay at home after work. I enjoy reading, especially adventure stories. I normally read for about 30 minutes before dinner.","Har doim emas. Hafta davomida koʻpincha ishdan keyin uyda qolaman. Kitob oʻqishni yaxshi koʻraman, ayniqsa sarguzasht hikoyalarini. Odatda kechki ovqatdan oldin taxminan 30 daqiqa oʻqiyman.",64.5],["Interviewer","Do you have any hobbies that you do with other people?","Boshqalar bilan birga qiladigan xobbilaringiz bormi?",76.9],["Anna","Yes. My friend Chloe and I go to a dance class together. We used to go on Tuesdays, but the class moved to Thursday this month. It starts at seven in the evening.","Ha. Doʻstim Chloe bilan birga raqs darsiga qatnaymiz. Avval seshanba kunlari borardik, lekin bu oy dars payshanbaga koʻchdi. U kechqurun soat yettida boshlanadi.",80.3],["Interviewer","That sounds busy. Do you have time to relax?","Band ekansiz. Dam olishga vaqtingiz bormi?",91.8],["Anna","Definitely. I don't like planning every minute of my free time. Some evenings, I just listen to music or watch something online.","Albatta. Boʻsh vaqtimning har daqiqasini rejalashtirishni yoqtirmayman. Baʼzi kechqurunlari shunchaki musiqa tinglayman yoki internetda biror narsa koʻraman.",96.1],["Interviewer","Is there anything new you'd like to try?","Yangi sinab koʻrmoqchi boʻlgan narsangiz bormi?",105.3],["Anna","Yes, actually. I'd really like to learn painting. There's an art club near my house, and I'm thinking about joining it next month.","Ha, aslida bor. Rasm chizishni juda oʻrganmoqchiman. Uyim yaqinida sanʼat klubi bor, kelasi oy unga aʼzo boʻlish haqida oʻylayapman.",108.3],["Interviewer","Sounds good. Thanks for answering my questions.","Yaxshi ekan. Savollarimga javob berganingiz uchun rahmat.",117.8],["Anna","You're welcome.","Arzimaydi.",121.3]],"q":[{"t":"How did Anna start photography?","o":["She bought a camera herself.","Her parents gave her a camera.","Her friend Chloe taught her."],"a":1},{"t":"When does Anna usually take photos in the town centre?","o":["On Saturday mornings","On Sunday evenings","On Tuesday afternoons"],"a":0},{"t":"How long does Anna normally read before dinner?","o":["About 15 minutes","About an hour","About 30 minutes"],"a":2},{"t":"Which day is Anna's dance class now?","o":["Tuesday","Thursday","Saturday"],"a":1,"why":"Dars avval seshanba edi, hozir payshanbaga koʻchgan."},{"t":"What would Anna like to learn?","o":["Painting","Dancing","Photography"],"a":0}]},
{"id":"sb-04","u":4,"book":"Student's Book","title":"Food, Cooking and Eating","dur":124,"audio":"audio/a2/student/unit-04.mp3","lines":[["Interviewer","Hello. I'm doing a survey about people's eating and cooking habits. Would you mind answering a few questions?","Salom. Men odamlarning ovqatlanish va ovqat pishirish odatlari boʻyicha soʻrovnoma oʻtkazyapman. Bir nechta savolga javob berolmaysizmi?",5.4],["Emily","Not at all.","Mayli, marhamat.",12.5],["Interviewer","Great. Could I have your name first?","Zoʻr. Avval ismingizni aytsangiz.",14.1],["Emily","Sure. I'm Emily Clark.","Albatta. Men Emily Clark.",17.3],["Interviewer","And how do you spell your surname?","Familiyangiz qanday yoziladi?",20.1],["Emily","It's C-L-A-R-K.","C-L-A-R-K.",22.6],["Interviewer","Thank you. Let's start with breakfast. What do you normally eat in the morning?","Rahmat. Nonushtadan boshlaylik. Odatda ertalab nima yeysiz?",26.6],["Emily","On work days, I need something quick. I used to have cereal every morning, but now I usually have yogurt with some fruit. I also drink tea, but I never have coffee.","Ish kunlari menga tez tayyor boʻladigan narsa kerak. Ilgari har ertalab quruq nonushta (kornfleks) yerdim, hozir esa odatda meva bilan yogurt yeyman. Choy ham ichaman, lekin kofe hech ichmayman.",31.9],["Interviewer","What about lunch?","Tushlik-chi?",43.9],["Emily","I work in an office, so I take my lunch with me. I normally make a sandwich at home. Sometimes I take soup instead, especially when the weather is cold.","Men idorada ishlayman, shuning uchun tushlikni oʻzim bilan olib boraman. Odatda uyda sendvich tayyorlayman. Baʼzan, ayniqsa havo sovuq boʻlganda, uning oʻrniga shoʻrva olaman.",45.8],["Interviewer","Do you enjoy cooking?","Ovqat pishirishni yoqtirasizmi?",56.8],["Emily","Yes, very much. I usually cook dinner at around seven o'clock. I don't make anything difficult during the week because I'm tired after work. Pasta is probably the easiest thing for me to make.","Ha, juda. Odatda kechki ovqatni soat yetti atrofida pishiraman. Hafta davomida murakkab narsa pishirmayman, chunki ishdan keyin charchagan boʻlaman. Makaron men uchun eng oson ovqat boʻlsa kerak.",59],["Interviewer","Do you cook every day?","Har kuni pishirasizmi?",72.6],["Emily","Almost. But on Friday evenings, I usually eat out with my sister. There's a small restaurant near her apartment that we both like.","Deyarli. Lekin juma kechqurunlari odatda opam bilan tashqarida ovqatlanaman. Uning kvartirasi yaqinida ikkimiz ham yoqtiradigan kichik restoran bor.",74.9],["Interviewer","What kind of food do you order there?","U yerda qanday taom buyurtma qilasiz?",83.8],["Emily","I often order chicken, but my favourite dish there is actually fish with rice and vegetables. My sister usually chooses pizza.","Koʻpincha tovuq buyurtma qilaman, lekin u yerdagi eng yaxshi koʻrgan taomim aslida sabzavotli guruch bilan baliq. Opam odatda pitsa tanlaydi.",86.3],["Interviewer","Do you ever cook with other people?","Boshqalar bilan birga ovqat pishirasizmi?",95.3],["Emily","Yes. On Sundays, my dad and I sometimes cook together. He's really good at making bread. I normally prepare the vegetables while he works on the main dish.","Ha. Yakshanba kunlari baʼzan dadam bilan birga pishiramiz. U non yopishni juda yaxshi biladi. Men odatda u asosiy taomni tayyorlayotganda sabzavotlarni tayyorlayman.",97.9],["Interviewer","Is there anything you'd like to learn to make?","Pishirishni oʻrganmoqchi boʻlgan narsangiz bormi?",109],["Emily","Definitely. I'd love to learn how to make cake. I can make simple biscuits, but cakes are still difficult for me.","Albatta. Tort pishirishni oʻrganishni juda xohlardim. Oddiy pechenye pishira olaman, lekin tortlar hali men uchun qiyin.",111.9],["Interviewer","Thanks, Emily. That's everything.","Rahmat, Emily. Hammasi shu.",120.3],["Emily","You're welcome.","Arzimaydi.",122.8]],"q":[{"t":"What does Emily usually have for breakfast now?","o":["Cereal","Yogurt with fruit","Coffee and toast"],"a":1,"why":"Ilgari kornfleks yerdi, hozir yogurt."},{"t":"What does Emily sometimes take for lunch when it is cold?","o":["Soup","Pasta","Pizza"],"a":0},{"t":"What time does Emily usually cook dinner?","o":["At about six","At about eight","At about seven"],"a":2},{"t":"What does Emily usually do on Friday evenings?","o":["She cooks with her dad.","She eats out with her sister.","She makes pasta at home."],"a":1},{"t":"What would Emily like to learn to make?","o":["Bread","Biscuits","Cake"],"a":2}]},
{"id":"sb-05","u":5,"book":"Student's Book","title":"Shopping and money","dur":120,"audio":"audio/a2/student/unit-05.mp3","lines":[["Assistant","Good afternoon. Customer services, how can I help you?","Xayrli kun. Mijozlarga xizmat koʻrsatish boʻlimi, sizga qanday yordam bera olaman?",4.9],["Tom","Hi, I bought a jacket from your shop yesterday, but I think I need to change it.","Salom, kecha sizning doʻkoningizdan kurtka sotib oldim, lekin uni almashtirishim kerak shekilli.",9.4],["Assistant","That's fine. Can I take your name first?","Yaxshi. Avval ismingizni olsam boʻladimi?",15.4],["Tom","Yes, it's Tom Harris.","Ha, men Tom Harris.",19],["Assistant","Could you spell your surname, please?","Familiyangizni harflab bera olasizmi?",21.6],["Tom","Sure, it's H-A-R-R-I-S.","Albatta, H-A-R-R-I-S.",24.7],["Assistant","Thank you. Now, what seems to be the problem with the jacket?","Rahmat. Endi kurtka bilan nima muammo boʻldi?",30.4],["Tom","I bought a medium, but it's too small. I tried a large one in another colour, and that fitted much better. So, I'd like a large, please.","Men oʻrta oʻlchamni olgandim, lekin u juda kichik. Boshqa rangdagi katta oʻlchamni kiyib koʻrdim, u ancha yaxshi keldi. Shuning uchun katta oʻlchamni xohlayman.",35.2],["Assistant","No problem. What colour did you buy?","Muammo yoʻq. Qanday rangni olgandingiz?",45],["Tom","Blue. I really like it, so I don't want to change the colour. I saw a black one too, but blue looks better on me.","Koʻk. Menga juda yoqadi, shuning uchun rangini almashtirmoqchi emasman. Qorasini ham koʻrgandim, lekin koʻki menga yarashadi.",48.2],["Assistant","Do you still have your receipt?","Chekingiz hali bormi?",56.5],["Tom","Yes, I do. The jacket was £45, but there was a special offer yesterday, so I actually paid £36 for it.","Ha, bor. Kurtka 45 funt edi, lekin kecha maxsus chegirma bor edi, shuning uchun aslida 36 funt toʻladim.",58.9],["Assistant","That's fine. You can exchange it at the shop. When would you like to come in?","Yaxshi. Uni doʻkonda almashtirishingiz mumkin. Qachon kelmoqchisiz?",68.2],["Tom","I'm working tomorrow, so I can't come then. I'm free on Thursday afternoon. Is that OK?","Ertaga ishlayman, shuning uchun kela olmayman. Payshanba kuni tushdan keyin boʻshman. Shu boʻladimi?",73.5],["Assistant","Yes, we're open until 8. Do you remember which branch you bought it from?","Ha, soat 8 gacha ochiqmiz. Qaysi filialdan olganingiz esingizdami?",80],["Tom","Yes. The one in the town centre, next to the big supermarket. I usually shop there because it's close to my office.","Ha. Shahar markazidagi, katta supermarketning yonidagi. Odatda u yerdan xarid qilaman, chunki u ofisimga yaqin.",85.8],["Assistant","Good. We currently have three large blue jackets there, so there should be one available for you.","Yaxshi. Hozir u yerda uchta katta oʻlchamli koʻk kurtka bor, demak sizga bittasi chiqishi kerak.",93.4],["Tom","Perfect. Do I need to bring anything apart from the jacket and receipt?","Zoʻr. Kurtka va chekdan boshqa nima olib kelishim kerak?",100.3],["Assistant","No. Just make sure the price label is still on the jacket.","Yoʻq. Faqat kurtkada narx yorligʻi turganiga ishonch hosil qiling.",105.1],["Tom","Yes, it is. I only tried the jacket on at home.","Ha, turibdi. Kurtkani faqat uyda kiyib koʻrganman.",109.8],["Assistant","Great. Then there shouldn't be any problem.","Zoʻr. Unda hech qanday muammo boʻlmasligi kerak.",114],["Tom","Thanks for your help.","Yordamingiz uchun rahmat.",117.3],["Assistant","You're welcome.","Arzimaydi.",119]],"q":[{"t":"What size does Tom want now?","o":["Medium","Large","Small"],"a":1},{"t":"How much did Tom pay for the jacket?","o":["£36","£45","£30"],"a":0,"why":"Kecha chegirma boʻlgani uchun u 45 emas, 36 funt toʻlagan."},{"t":"When will Tom go to the shop?","o":["Tomorrow","Thursday morning","Thursday afternoon"],"a":2},{"t":"What time does the shop close?","o":["6 o'clock","8 o'clock","10 o'clock"],"a":1},{"t":"Why does Tom usually shop at that branch?","o":["It is close to his office.","It is next to his home.","It has special offers every day."],"a":0}]},
{"id":"sb-06","u":6,"book":"Student's Book","title":"School, learning and study","dur":130,"audio":"audio/a2/student/unit-06.mp3","lines":[["Receptionist","Good morning. Welcome to Westfield Language School. How can I help you?","Xayrli tong. Westfield til maktabiga xush kelibsiz. Sizga qanday yordam bera olaman?",5.8],["Nina","Hi. I'd like some information about your evening English classes.","Salom. Kechki ingliz tili darslaringiz haqida maʼlumot olmoqchiman.",11.1],["Receptionist","Of course. I'll take a few details first. What's your name?","Albatta. Avval bir oz maʼlumot yozib olaman. Ismingiz nima?",16.3],["Nina","Nina Cooper.","Nina Cooper.",21.3],["Receptionist","Could you spell your surname, please?","Familiyangizni harflab bera olasizmi?",22.8],["Nina","Yes. It's C-O-O-P-E-R.","Ha. C-O-O-P-E-R.",25.6],["Receptionist","Thank you. Have you studied English before?","Rahmat. Ilgari ingliz tilini oʻrganganmisiz?",30.8],["Nina","Yes. I studied it at school for about four years. I can have simple conversations, but I still make quite a lot of mistakes.","Ha. Maktabda taxminan toʻrt yil oʻrganganman. Oddiy suhbat qura olaman, lekin hali ancha xato qilaman.",34.5],["Receptionist","That's fine. You'll take a short level test before you start. Now, our evening classes are on Mondays and Wednesdays. Would both days be possible for you?","Mayli. Boshlashdan oldin qisqa daraja testini topshirasiz. Endi, kechki darslarimiz dushanba va chorshanba kunlari. Ikkala kun ham sizga qulaymi?",44.1],["Nina","Yes. I work during the day, but my evenings are usually free.","Ha. Kunduzi ishlayman, lekin kechqurunlari odatda boʻsh boʻlaman.",55],["Receptionist","Excellent. The class begins at 6 o'clock and finishes at 7.30. There's a short break in the middle.","Juda yaxshi. Dars soat 6 da boshlanadi va 7.30 da tugaydi. Oʻrtasida qisqa tanaffus bor.",60.2],["Nina","That sounds good. How many students are there in each class?","Bu yaxshi eshitilyapti. Har bir guruhda nechta oʻquvchi bor?",67.8],["Receptionist","We try to keep the groups small. There are usually about 10 students and the maximum is 12.","Biz guruhlarni kichik saqlashga harakat qilamiz. Odatda taxminan 10 oʻquvchi boʻladi, eng koʻpi 12 ta.",72.3],["Nina","Great. I find it difficult to speak when there are too many people.","Zoʻr. Odam juda koʻp boʻlsa, gapirish menga qiyin.",78.9],["Receptionist","Then this class should suit you. The teacher spends a lot of time on conversation, but you'll also practice reading, writing and listening. Students often say that speaking is their favourite part of the course.","Unda bu guruh sizga mos boʻlsa kerak. Oʻqituvchi suhbatga koʻp vaqt ajratadi, lekin oʻqish, yozish va tinglashni ham mashq qilasiz. Oʻquvchilar koʻpincha kursning eng yoqimli qismi gapirish deyishadi.",83.7],["Nina","That's exactly what I need. How much does the course cost?","Aynan menga kerak narsa shu. Kurs qancha turadi?",96.9],["Receptionist","It's £90 a month. That includes your lessons, but you need to buy the course book separately. It costs £18.","Oyiga 90 funt. Bunga darslar kiradi, lekin kurs kitobini alohida sotib olishingiz kerak. U 18 funt turadi.",101.7],["Nina","OK. And where are the evening classes held?","Mayli. Kechki darslar qayerda oʻtadi?",110.3],["Receptionist","Most lessons are upstairs, but your group will be in room 12 on the ground floor.","Darslarning koʻpi yuqori qavatda, lekin sizning guruhingiz birinchi qavatdagi 12-xonada boʻladi.",114.5],["Nina","Perfect. When can I take the level test?","Zoʻr. Daraja testini qachon topshirsam boʻladi?",120.4],["Receptionist","You can come in tomorrow afternoon, if you like.","Xohlasangiz, ertaga tushdan keyin kelishingiz mumkin.",124.1],["Nina","Great. I'll do that. Thank you.","Zoʻr. Shunday qilaman. Rahmat.",127]],"q":[{"t":"How long did Nina study English at school?","o":["Ten years","Two years","Four years"],"a":2},{"t":"On which days are the evening classes?","o":["Mondays and Wednesdays","Tuesdays and Thursdays","Mondays and Fridays"],"a":0},{"t":"What time does the class finish?","o":["6.00","7.00","7.30"],"a":2},{"t":"How much is the course book?","o":["£90","£18","£12"],"a":1,"why":"90 funt kursning oyiga narxi, kitob alohida 18 funt."},{"t":"Where will Nina's group have lessons?","o":["Room 12 on the ground floor","Room 12 upstairs","Room 10 on the ground floor"],"a":0}]},
{"id":"sb-07","u":7,"book":"Student's Book","title":"Jobs and Working Life","dur":124,"audio":"audio/a2/student/unit-07.mp3","lines":[["","Good morning, Park Hotel. You're calling about the weekend job, right?","",4.9],["","Yes, I saw the advertisement online yesterday and I'd like some more information.","",10.2],["","Of course. Before we start, can I take your name?","",16.1],["","It's Jamie Lewis.","",20.2],["","And could you spell your surname?","",22.4],["","Yes, it's L-E-W-I-S.","",25.1],["","Thanks. The job is in our restaurant. We're looking for someone to help the waiters and clear the tables.","",30.5],["","Have you worked in a restaurant before?","",37.4],["","No, but I worked in a cafe last summer. I served drinks and helped prepare sandwiches.","",40.1],["","That's useful experience. The restaurant gets quite busy, especially at lunchtime,","",46.6],["","so you need to work quickly.","",52.2],["","That's fine. I'm used to working with lots of customers.","",54.6],["","Good. At the moment, we need someone on Saturday and Sunday. The Saturday shift starts at 10,","",58.6],["","but on Sunday you start at 1100 because breakfast finishes later.","",65.9],["","Okay, and what time would I finish?","",71.1],["","Usually around 4. You'll get a 30-minute lunch break during the afternoon.","",74.6],["","Great. What should I wear?","",80.3],["","We provide a shirt, but you need to wear your own black trousers.","",83.3],["","Please don't wear jeans.","",88],["","No problem. And how much does the job pay?","",90.2],["","It's £11 an hour. You also get a free meal during each shift.","",94.1],["","That sounds good.","",99.6],["","If you're interested, you'll need to come for a short interview.","",101.4],["","We're interviewing people on Thursday afternoon.","",105.1],["","Thursday's fine. Where should I go when I arrive?","",108.4],["","Come to the main entrance and ask for Mrs Green at reception.","",112.6],["","She'll take you to the manager's office.","",116.9],["","Perfect. Thanks very much.","",119.5],["","You're welcome. See you then.","",122]]},
{"id":"sb-08","u":8,"book":"Student's Book","title":"Travel and Transport","dur":127,"audio":"audio/a2/student/unit-08.mp3","lines":[["","Good morning, City Travel Centre. How can I help you?","",4.7],["","Hi, I'd like some information about buses to Lakeside.","",8.6],["","I'm planning to go there this weekend.","",12.5],["","Certainly. Are you travelling alone?","",15],["","Yes, I'm visiting a friend who lives there.","",18.2],["","OK, before we look at the times, can I take your name?","",22],["","Sure, it's Alex Morgan.","",26.9],["","Could you spell your surname, please?","",29.8],["","Yes, it's M-O-R-G-A-N.","",32.7],["","Thanks. Now, which day are you planning to travel?","",38.3],["","Saturday. I thought about going on Friday evening, but I have to work late that day.","",42.9],["","No problem. There are several buses on Saturday morning.","",49.3],["","The first one leaves at 7.30, but the next bus at 8.15 is usually more convenient.","",53.1],["","Yes, 7.30 is a little early. How long does the journey take?","",60.4],["","Normally about an hour and 20 minutes. However, there are some road works this weekend,","",66.1],["","so it may take slightly longer.","",72],["","That's OK. How much is a return ticket?","",74.8],["","A single is £9. The return ticket is £15,","",78.3],["","so that's better value if you're coming back the same weekend.","",83.3],["","Yes, I'm returning on Sunday. Where does the bus leave from?","",87.2],["","From Central Station, but not from the main bus area.","",91.9],["","You need to go to Platform 6, which is near the cafe.","",96.2],["","OK, can I buy the ticket on the bus?","",100.2],["","You can, but weekend buses are often crowded,","",103.5],["","so I recommend booking your ticket before you travel.","",107.3],["","Good idea. Can I take a suitcase?","",111],["","Yes. One suitcase can go underneath the bus,","",114.3],["","and you can take a small bag with you to your seat.","",118],["","Perfect. I'll book the ticket online today.","",121.4],["","Great. Have a good trip.","",125]]},
{"id":"sb-09","u":9,"book":"Student's Book","title":"Cities, Towns and Neighbourhoods","dur":132,"audio":"audio/a2/student/unit-09.mp3","lines":[["","Hello, welcome to the new residence centre. Are you new to the area?","",5.5],["","Yes, I moved here last week, so I'm still trying to find out where everything is.","",10.7],["","Of course, I can give you some information. Can I take your name first?","",16.7],["","Sure, I'm Laura Dawson.","",21.9],["","Could you spell your surname, please?","",25],["","Yes, it's D-A-W-S-O-N.","",27.7],["","Thank you. And which part of town are you living in?","",33],["","I've got a flat in Riverside. It's quite a quiet neighbourhood, near the river.","",36.7],["","Oh, that's a nice area. There are several useful places nearby.","",42.6],["","There's a supermarket on King Street and a small market every Saturday morning.","",47.5],["","Great. I also need somewhere to exercise. Is there a gym near my flat?","",52.9],["","There is, but the sports centre is probably better. It has a gym and a swimming pool.","",59],["","It opens at six in the morning and closes at nine o'clock in the evening.","",65],["","That's perfect, because I sometimes exercise after work.","",69.5],["","You might also want to join the local library. It moved recently. It used to be next to the","",74.2],["","post office, but now it's opposite the museum.","",79.7],["","Good to know. I enjoy reading, so I'll definitely visit it.","",83],["","There's also a lovely park about ten minutes from Riverside.","",88.1],["","It's usually quiet during the week, although it gets quite busy on sunny weekends.","",91.9],["","I'd like somewhere to walk in the evenings.","",96.9],["","Then you'll enjoy it. There's a small lake and a café there too.","",99.9],["","Sounds great. What's the easiest way to get into the town centre?","",104.6],["","Bus number 14 goes directly from Riverside. It runs every 20 minutes during the day.","",109.8],["","Excellent. Is there anything else I should know?","",116.6],["","Yes. On Fridays, there's a street market in the main square.","",120.3],["","It's a good place to buy fresh fruit and vegetables.","",124.8],["","Thanks. This has been really helpful.","",128.2]]},
{"id":"sb-10","u":10,"book":"Student's Book","title":"Technology and Everyday Life","dur":126,"audio":"audio/a2/student/unit-10.mp3","lines":[["","Good afternoon. Tech Help Centre. How can I help you?","",5.3],["","Hi. I'm having a problem with my new tablet. I bought it from your shop last week.","",9.5],["","I'm sorry about that. I'll take a few details first. What's your name?","",15.4],["","It's Ryan Baker. Could you spell your surname, please?","",21.3],["","Sure. It's B-A-K-E-R.","",25],["","Thank you. Now, what exactly is wrong with the tablet?","",31.4],["","The screen is fine, and I can use most of the apps, but the camera isn't working. When I try","",35.8],["","to take a photo, the screen goes black. I see. Have you tried turning the tablet off and on again?","",41.9],["","Yes. Twice. I also charged it fully last night, but that didn't help.","",49.9],["","OK. Which model do you have?","",55.7],["","It's the T20. I nearly bought the T15 because it was cheaper, but I chose the T20 because it has","",58.7],["","more storage. Right. We can check it for you at the shop. When are you free to bring it in?","",66],["","I'm busy tomorrow, but I can come on Wednesday afternoon.","",73],["","That's fine. Our repair desk is open from 10 until 6. If you come before 4,","",77.2],["","we can probably check it the same day. Great. Do I need to bring the box?","",83.4],["","No, but please bring your receipt. We need to check when and where you bought the tablet.","",89.3],["","No problem. I still have it.","",95.6],["","Good. If it's a simple software problem, the repair should take about 30 minutes.","",98.2],["","If there's a problem inside the tablet, we may need to keep it for a few days.","",104.3],["","OK. Is there a charge for checking it?","",109.6],["","Normally it costs £20, but because your tablet is new, the check is free.","",113.3],["","Excellent. Thanks for your help.","",119.8],["","You're welcome. We'll see you on Wednesday.","",122.3]]},
{"id":"sb-11","u":11,"book":"Student's Book","title":"Health, Exercise and Sleep","dur":143,"audio":"audio/a2/student/unit-11.mp3","lines":[["","Good morning. Active Life Centre. How can I help you?","",5.7],["","Hi. I'd like to join one of your exercise classes.","",9.8],["","I want to become more active, but I'm not sure which class is best for me.","",13.5],["","No problem. I'll ask you a few questions first. What's your name?","",18.4],["","It's Daniel Price.","",23.4],["","Could you spell your surname, please?","",25.5],["","Yes. It's P-R-I-C-E.","",27.4],["","Thanks. How much exercise do you do at the moment?","",33.7],["","Not enough, really. I walk to work most days, but that only takes about 15 minutes.","",38],["","At weekends, I sometimes go cycling, but not regularly.","",44],["","OK. How are your energy levels during the day?","",48.3],["","I'm usually fine in the morning, but I often feel tired after lunch.","",52.5],["","That's one reason I want to exercise more.","",57.2],["","Exercise may help. We have a beginner fitness class that could suit you.","",60.3],["","It's on Monday and Wednesday evenings.","",65],["","What time does it start?","",68.1],["","The Monday class starts at 6, but Wednesday's class begins at 6.30.","",70.1],["","Wednesday would be easier, because I sometimes work late on Mondays.","",75.8],["","Great. Each class lasts 45 minutes.","",80.5],["","You'll do some simple exercises, but there's no running.","",84.1],["","Good. I'm not a big fan of running.","",88.2],["","What about sleep? How many hours do you usually get?","",91.5],["","Only about six hours. I often stay up too late watching videos, even when I have to get up early.","",96.2],["","You should try to get a little more sleep.","",103.4],["","It's also a good idea to stop using screens before bed.","",106],["","Yes, I know. I'm trying to leave my phone in the living room at night instead of taking it to bed.","",110.2],["","That's a good habit. Now, for the exercise class,","",116.6],["","please bring comfortable clothes and a bottle of water.","",120.6],["","Do I need special shoes?","",124.7],["","Just clean sports shoes. You'll also need a small towel,","",127.3],["","because some of the exercises can make you quite warm.","",131.2],["","Fine. How much is the class?","",135.2],["","Your first class is free, so you can try it before deciding whether to join.","",137.3]]},
{"id":"sb-12","u":12,"book":"Student's Book","title":"Sports and competitions","dur":129,"audio":"audio/a2/student/unit-12.mp3","lines":[["","Good afternoon. Westside Sports Club. How can I help?","",4.4],["","Hi. I saw a poster about your summer sports competition and I'd like to take part.","",9.7],["","Great. I can register you now. Can I have your name first?","",15.8],["","Yes. It's Oliver Kent. Could you spell your surname, please?","",21.1],["","Of course. It's K-E-N-T.","",26.4],["","Thank you. We have competitions in tennis, basketball and badminton. Which one are you interested in?","",31.4],["","I play basketball quite often, but I'm already in a competition at college. I'd like to enter the tennis competition here.","",39.4],["","No problem. Have you played tennis for long?","",47.4],["","About three years. I usually play with my brother at weekends. I'm not an excellent player but I really enjoy it.","",50.4],["","That's the important thing. The competition is on Saturday the 18th. It was originally planned for Sunday that we had to change the day.","",58.4],["","Saturday is fine. What time does it start?","",68.4],["","The first matches begin at 10, but all players must arrive by 9.30. That gives us enough","",72.4],["","time to check everyone's names and explain the rules.","",79.3],["","OK, do I need to bring my own equipment?","",83],["","We provide tennis balls, but you should bring your own racket. We have a few spare ones,","",86.7],["","but they're mainly for emergencies.","",92.5],["","That's fine. How much is it to enter?","",94.6],["","The normal price is £12, but club members pay only £8.","",98.3],["","I joined the club last month, so I can pay the lower price, right?","",104.2],["","Exactly! There will also be water and fruit for all the players.","",108.6],["","Great! Where should I go when I arrive?","",113.7],["","Go to the main sports hall and ask for Martin. He'll show you which court you're playing","",117.5],["","on.","",122.6],["","Perfect! I'm looking forward to it!","",123.6],["","Excellent! Good luck!","",126.3]]},
{"id":"sb-13","u":13,"book":"Student's Book","title":"Weather and seasonal activities","dur":127,"audio":"audio/a2/student/unit-13.mp3","lines":[["","Good morning. Green Valley Activity Centre. How can I help?","",6],["","Hi. My family is visiting Green Valley next weekend and I'd like some information about","",10.6],["","your outdoor activities. Of course. I can help with that. Could I take your name first?","",16.7],["","Yes, it's Megan Frost. Could you spell your surname, please?","",23.8],["","Sure. It's F-R-O-S-T.","",29.4],["","Thank you. What kind of activity are you interested in?","",34.3],["","We wanted to go cycling, but I checked the weather this morning and it looks quite wet.","",38.3],["","Is there anything else we could do?","",43.9],["","Yes. The forecast says there will be rain on Saturday morning,","",46.4],["","but the afternoon should be much drier.","",50.7],["","That's good. We'd still like to spend some time outside.","",53.5],["","In that case, you could join our afternoon forest walk.","",57.7],["","It starts at 2.30 and lasts about two hours.","",61.2],["","That sounds nice. Is it suitable for children?","",65.1],["","Yes. The route is easy and families often join us.","",69.1],["","However, the paths can be wet at this time of year,","",73.2],["","so everyone should wear boots rather than ordinary shoes.","",76.6],["","OK. We can bring those. What about Sunday?","",80.6],["","Sunday should be sunny, although it may be a little cold in the morning.","",84.8],["","It should reach about 16 degrees in the afternoon.","",89.3],["","Great. Maybe we could go cycling then?","",92.8],["","Definitely. We rent bicycles here.","",96.2],["","An adult bicycle costs £12 for the day and a child's bicycle costs £8.","",99],["","Perfect. Do we need to book them?","",105.4],["","At weekends, yes. Spring is a very popular time for cycling here,","",108.4],["","especially when the weather is good.","",113.3],["","OK. I'll book them today.","",115.6],["","Great. And remember to bring a light jacket,","",118.2],["","because the evenings can still be cool.","",121.1],["","We will. Thanks for your help.","",124.3]]},
{"id":"sb-14","u":14,"book":"Student's Book","title":"Animals and Wildlife","dur":125,"audio":"audio/a2/student/unit-14.mp3","lines":[["","Good morning, Greenhill Wildlife Park","",4],["","how can I help? Hi, I'm planning to visit the park with my family this weekend","",7.9],["","and I'd like some information. Of course","",13.6],["","are you interested in any particular animals? My children really want to see","",16.9],["","the monkeys","",22.4],["","but I'd like to see everything if we have enough time.","",23.3],["","Certainly. Before we continue could I take your name?","",27.1],["","Yes, I'm Helen Webb. Could you spell your surname please?","",30.8],["","Sure, it's W-E-B-B.","",36.1],["","Thank you. Which day are you thinking of visiting?","",40.3],["","We're coming on Sunday. We originally planned to come on Saturday","",43.9],["","but my son has a football match. No problem.","",48.5],["","The park opens at nine. If your children like monkeys","",51.8],["","there's a feeding session at 10.30. A member of staff talks about the animals","",55.6],["","while they eat.","",60.2],["","They'll love that! Where are the monkeys?","",61],["","They're in the forest area just past the lake.","",64.5],["","You'll also see several kinds of birds there. Some of them are very colourful","",67.8],["","so it's a popular place for photographs. Great!","",73],["","Are there any baby animals at the moment? Yes","",76.8],["","we have two young bears. They were born earlier this year","",80.9],["","and have recently started coming outside with their mother.","",84.9],["","Wonderful! My children will be excited about those.","",88.4],["","There's also a short wildlife talk in the afternoon.","",93.2],["","It starts at two and explains how we care for the animals.","",96.5],["","Is there somewhere to eat? Yes.","",100.7],["","The cafe is next to the main entrance. You can also bring your own food","",103.8],["","and use the picnic area near the river. Good!","",108.2],["","How much are children's tickets? Adults are 14 pounds","",111.9],["","and a child's ticket is nine pounds. Children under three","",116.4],["","enter free. Perfect! Thanks for all the information.","",120.6]]},
{"id":"sb-15","u":15,"book":"Student's Book","title":"Nature and the Environment","dur":128,"audio":"audio/a2/student/unit-15.mp3","lines":[["","Hello, Green Town Project. How can I help?","",3.9],["","Hi, I saw your poster about the community clean-up and I'd like to join.","",9],["","That's great. We're still looking for volunteers. Can I take your name first?","",14.6],["","Yes, I'm Ben Russell. Could you spell your surname, please?","",20.5],["","Sure. It's R-U-S-S-E-L-L.","",26.2],["","Thank you. We're cleaning several outdoor areas this month.","",32],["","The next event is at Lakewood Park. Have you been there before?","",36.2],["","Yes. I sometimes go there for walks. It's a beautiful place.","",40.6],["","But I noticed quite a lot of rubbish near the lake last weekend.","",45.4],["","That's one of the reasons we chose it. We're meeting this Saturday.","",49.7],["","We considered Sunday, but the park is usually much busier then.","",54],["","Saturday is fine. What time should I arrive?","",58.6],["","We'll start cleaning at ten, but volunteers should arrive by nine forty-five.","",62],["","That gives us time to explain what everyone needs to do.","",67.4],["","Okay. Do I need to bring anything?","",71],["","We provide rubbish bags and gloves. Please bring a bottle of water and wear comfortable clothes.","",74.2],["","Strong shoes are also a good idea because the ground near the lake can be muddy.","",80.6],["","No problem. What kind of rubbish do you usually find?","",86],["","Mostly plastic bottles, paper and food packaging.","",90.3],["","We separate everything we collect so that as much as possible can be recycled.","",94.4],["","That makes sense. How long will the clean-up take?","",99.8],["","About three hours. At one o'clock we'll stop and have lunch together.","",103.6],["","We provide sandwiches, but volunteers should bring their own drink.","",108.4],["","Great. Can children take part too?","",112.8],["","Yes, but anyone under sixteen needs to come with an adult.","",116.2],["","Perfect. I might bring my younger brother.","",121.4],["","Excellent. The more people we have, the better.","",124.3]]},
{"id":"sb-16","u":16,"book":"Student's Book","title":"Films, music, books and entertainment","dur":127,"audio":"audio/a2/student/unit-16.mp3","lines":[["","Good afternoon. Central Arts Centre. How can I help?","",6.8],["","Hi. I saw a poster about your film and music weekend and I'd like some more information.","",11.1],["","Of course. Are you interested in booking something?","",18.1],["","Yes, probably. I'm coming with a friend.","",22],["","Great. Before we start, can I take your name?","",26],["","Sure. I'm Amy Stone.","",29.9],["","Could you spell your surname, please?","",32.6],["","Yes. It's S-T-O-N-E.","",35.5],["","Thank you. The festival starts on Friday evening, but most activities are on Saturday.","",40.7],["","There are films, live music and a book event.","",46.6],["","Saturday is better for us. What films are you showing?","",50.3],["","There's a comedy in the afternoon and an adventure film in the evening.","",54.3],["","The comedy starts at 2, but the adventure film begins at 6.30.","",58.6],["","I think we'd prefer the adventure film.","",63.5],["","That's been very popular. It's about a group of friends who travel across South America","",66.6],["","looking for a lost village.","",71.8],["","Sounds interesting. Is there any live music?","",74],["","Yes. After the film, a local band will play in the main hall.","",77.8],["","They mostly play pop and rock music.","",82.1],["","Great. What about the book event you mentioned?","",85.1],["","A travel writer called James Wood is giving a short talk.","",88.8],["","He'll speak about his new book and answer questions from the audience.","",92.8],["","I'd like that too. How much are tickets?","",97.3],["","You can buy separate tickets, but the full day ticket is better value.","",100.8],["","It used to be £20, but this year it costs £18.","",105.3],["","That sounds reasonable. Do we need to book in advance?","",110.1],["","I recommend it. Last year, the evening events were completely full by Friday morning.","",114.2],["","Okay. I'll book two tickets online tonight.","",120.4],["","Excellent. I hope you both enjoy the festival.","",124.1]]},
{"id":"sb-17","u":17,"book":"Student's Book","title":"Interesting people and their lives","dur":123,"audio":"audio/a2/student/unit-17.mp3","lines":[["","Welcome back to People in Our Town. Today I'm","",4.5],["","talking to a young photographer who has travelled to many interesting places. Thanks for joining us.","",9],["","Could you introduce yourself? Sure. My name is Nina Hayes.","",14.7],["","And could you spell your surname for our listeners? Of course. It's H-A-Y-E-S.","",20],["","Thanks Nina. Where did you grow up?","",27.9],["","I was born in London, but my family moved when I was very young. I actually grew up in a small village near Oxford. There were only about 500 people there.","",31.9],["","When did you become interested in photography?","",42.9],["","When I was 14, my grandfather gave me his old camera for my birthday. At first I just took pictures of my family and friends.","",45.9],["","Did you study photography later?","",54.9],["","Yes. After school, I studied art at college for two years. I wanted to study painting at first, but I decided to choose photography because I enjoyed it more.","",57.9],["","And when did you start travelling?","",69.9],["","My first big trip was to Italy. I stayed there for three months and took hundreds of pictures. After that, I visited several other countries.","",71.9],["","Which place has been your favourite?","",82.9],["","Probably Japan. I spent six weeks there last year.","",84.9],["","I loved the busy cities, but I also visited some beautiful quiet places in the countryside.","",89.9],["","What do you photograph most often now?","",96.9],["","I used to take lots of pictures of buildings, but these days I mainly photograph people.","",99.9],["","I enjoy meeting someone and learning a little about their life before taking their picture.","",105.9],["","Do you have any plans for the future?","",111.9],["","Yes. Next year I want to make a book of my favourite photographs.","",114.9],["","That sounds exciting. Good luck with it.","",119.9]]},
{"id":"sb-18","u":18,"book":"Student's Book","title":"Festivals, Celebrations and Traditions","dur":126,"audio":"audio/a2/student/unit-18.mp3","lines":[["","Good morning, Riverside Festival Office.","",5.3],["","How can I help? Hi, my family has just moved to the area","",9],["","and we'd like some information about the Summer Festival.","",13.8],["","Of course, it's one of our biggest celebrations of the year.","",17],["","Can I take your name first? Yes,","",21.1],["","I'm Anna Mitchell. Could you spell your surname please?","",24.6],["","Sure, it's M-I-T-C-H-E-L-L.","",29.4],["","Thank you. The festival is usually held on the first Saturday in July,","",36.6],["","but this year it will be on Sunday because there's another large event on Saturday.","",41.5],["","Great! What time does everything begin?","",46.6],["","The market opens at 10, but the main celebration starts at 11.30 with a parade through the town centre.","",50.2],["","My children would enjoy that. What happens after the parade?","",57.7],["","There's live music in Riverside Park. We'll also have traditional dancing,","",62.2],["","games for children and plenty of food.","",67],["","What kind of traditional food can we try?","",70.2],["","Several things, but our local bread is especially popular.","",73.5],["","It's made fresh in the morning and visitors can watch how it's prepared.","",77.8],["","That sounds interesting. Do people wear anything special?","",82.2],["","Some of the dancers wear traditional clothes. Visitors can wear whatever they like,","",86.8],["","although many people choose something colourful because it makes the festival feel more cheerful.","",92.2],["","Is there anything in the evening? Yes. At seven there's a concert,","",97.7],["","and later there will be fireworks near the river. They begin when it gets dark.","",102.8],["","Do we need tickets? Most activities are free.","",108.2],["","The evening concert costs £5 for adults, but children can enter free.","",112.1],["","Perfect! We'll definitely come.","",117.4],["","Wonderful! I hope your family enjoys its first Riverside Festival.","",120.5]]},
{"id":"sb-19","u":19,"book":"Student's Book","title":"Childhood and Memories","dur":119,"audio":"audio/a2/student/unit-19.mp3","lines":[["","Welcome to Memories of Home. Today we're talking to people","",4.6],["","about their childhood. Could you introduce yourself? Sure. My name's Rachel Perry.","",9.2],["","Could you spell your surname for us? Yes, it's P-E-R-R-Y. Thanks, Rachel. Where did you grow up?","",16.3],["","I grew up in a small town near the sea. It wasn't a very busy place,","",26.7],["","but I loved living there because we could walk to the beach.","",32.1],["","What was your home like?","",35.3],["","We lived in an old house with a large garden. I shared a bedroom with my younger sister until","",37.9],["","I was 12. We sometimes argued because she was untidy, but we were very close.","",44.7],["","What do you remember about school?","",50.2],["","I went to a small primary school about 15 minutes from our house.","",53.2],["","I usually walked there with two friends.","",58.2],["","My favourite subject was art because I loved drawing and making things.","",61.2],["","What did you do after school?","",66.2],["","We spent a lot of time outside.","",69.2],["","There weren't many computer games in our house,","",71.2],["","so my friends and I usually played in the garden or rode our bikes around the neighbourhood.","",74.2],["","Did your family have any special weekend routines?","",79.2],["","Yes, every Saturday morning my dad took us to the market.","",83.2],["","In the afternoon we often visited my grandparents.","",88.2],["","My grandmother always made cake for us.","",91.2],["","That sounds like a nice memory.","",94.2],["","What about holidays?","",97.2],["","Every summer we went camping for a week.","",99.2],["","My favourite trip was when I was 14.","",102.2],["","We stayed near a lake and I learnt to swim there.","",105.2],["","Do you still visit the town where you grew up?","",108.2],["","Yes, usually once or twice a year. It has changed a lot, but it still feels like home.","",111.2]]},
{"id":"sb-20","u":20,"book":"Student's Book","title":"Everyday problems and solutions","dur":129,"audio":"audio/a2/student/unit-20.mp3","lines":[["","Good morning. West Park Apartments. How can I help you?","",6],["","Hi. I live in one of your apartments and I need to report a problem.","",9.8],["","Of course. Can I take your name first?","",15.4],["","Yes. I'm Emma Walsh.","",18.7],["","Could you spell your surname, please?","",21.6],["","Sure. It's W-A-L-S-H.","",24.4],["","Thank you. And which apartment are you in?","",29.3],["","Apartment 24 on the second floor. I moved in about three months ago.","",32.9],["","Okay. What seems to be the problem?","",38.8],["","There's something wrong with the shower. The water was fine yesterday morning,","",42.1],["","but last night it suddenly became cold. I tried it again this morning and it's still cold.","",46.8],["","I see. Is there hot water anywhere else in the apartment?","",54.2],["","Yes. The kitchen tap is working normally, so I think the problem is only in the bathroom.","",58.9],["","All right. We'll need to send someone to look at it. Are you at home today?","",66.1],["","I'm at work until five. I could be home by five thirty, but not before then.","",71.3],["","That should be fine. Our repair person can come between five thirty and seven.","",77.5],["","Great. Will I need to pay anything?","",83.2],["","No. Bathroom repairs like this are free for residents, unless the problem was caused by damage.","",86.4],["","Okay. That's good.","",92.9],["","Is there anything else you'd like us to check?","",95.4],["","Actually, yes. The light in the kitchen is also very weak. I changed the bulb,","",98.2],["","but it didn't make any difference.","",104.5],["","I'll add that to the repair request. The repair person can check both problems.","",107.1],["","Perfect. What should I do if I'm late getting home?","",112.5],["","Call the office on seven three oh four one eight six. Someone will be here until seven.","",117],["","Great. I'll write that down. Thanks for your help.","",123.6],["","You're welcome.","",127.4]]},
{"id":"sb-21","u":21,"book":"Student's Book","title":"Helping people and community life","dur":129,"audio":"audio/a2/student/unit-21.mp3","lines":[["","Good morning, Brookside Community Centre. How can I help?","",6.2],["","Hi, I saw your notice asking for volunteers and I'd like to help.","",10.3],["","That's great. We have several volunteer activities at the moment. Can I take your name first?","",15.9],["","Sure, I'm Alice Young.","",22.3],["","Could you spell your surname, please?","",25],["","Yes, it's Y-O-U-N-G.","",27.8],["","Thank you. What kind of volunteer work are you interested in?","",33],["","I enjoy working with older people. I used to visit my grandmother every week and I often","",37.3],["","helped her with shopping and things around the house.","",43.3],["","Then our shopping service might suit you. Volunteers help older residents who find it","",46.6],["","difficult to carry heavy bags home.","",51.7],["","That sounds like something I could do.","",54.4],["","Good. We need volunteers on Tuesday and Thursday afternoons. Tuesday's almost full,","",57],["","so Thursday would be more useful for us.","",62.8],["","Thursday is fine. I finish work early that day.","",65.9],["","Excellent. Volunteers meet here at the community centre at 2.15. We give everyone a shopping","",70],["","list and an address before they leave.","",76.3],["","How long does it usually take?","",79.8],["","About two hours. Most volunteers help one or two people each afternoon.","",82.4],["","Do I need a car?","",88.2],["","No. All the homes are nearby. Most volunteers walk, although some people use bicycles.","",90.2],["","Great. Is there anything I should bring?","",96.9],["","We provide shopping bags, but please bring a phone in case you need to contact the centre","",100.1],["","while you're out.","",105],["","OK. Is there any training before I start?","",106.7],["","Yes. Just a short meeting. The next one is on Monday evening and lasts about 40 minutes.","",110.6],["","Perfect. I can come to that.","",117.5],["","Wonderful. We really appreciate your help.","",120.2],["","The service is very important to people in the neighbourhood.","",123.4],["","I'm happy to help.","",127.1]]},
{"id":"sb-22","u":22,"book":"Student's Book","title":"Trying something new","dur":138,"audio":"audio/a2/student/unit-22.mp3","lines":[["","Good afternoon. Adventure club, how can I help?","",5.2],["","Hi, I saw your advertisement for beginner activities.","",9.1],["","I'd like to try something new, but I'm not sure which activity to choose.","",13.3],["","No problem. Can I take your name first?","",18.9],["","Yes, I'm Jessica Miles.","",22.2],["","Could you spell your surname, please?","",25.2],["","Sure. It's M-I-L-E-S.","",28],["","Thank you. Have you done any adventure sports before?","",33.1],["","Not really. I go swimming sometimes and I ride my bike at weekends,","",37],["","but I've never tried anything very exciting.","",42.5],["","Well, we have several activities for beginners.","",45.8],["","You could try climbing, kayaking or horse riding.","",48.9],["","I'm a little afraid of heights, so climbing probably isn't for me.","",53.1],["","I think kayaking sounds the most interesting.","",58.1],["","Good choice. Our beginner kayaking sessions take place at Blue Lake.","",61.4],["","You don't need any previous experience.","",66],["","Great. When are the sessions?","",69],["","We have them on Saturday and Sunday mornings.","",71.6],["","Saturday is nearly full this week, so the other day would be better.","",74.6],["","Sunday is fine. What time does it start?","",79],["","The activity starts at 10, but everyone needs to arrive by 9.30.","",82.6],["","The instructor will explain the safety rules before you go onto the water.","",87.4],["","Okay. Do I need to bring any special equipment?","",91.8],["","We provide the kayak, helmet and life jacket.","",95.8],["","You should bring a towel and some dry clothes because you may get wet.","",99.1],["","I expected that. How long does the session last?","",103.6],["","About two hours. There's a short break halfway through.","",107.8],["","And how much does it cost?","",112.2],["","The normal price is £25, but your first beginner session costs £18.","",114.6],["","That sounds good. I'd like to book it.","",120.9],["","Excellent. One final thing. The water can be quite cold, even in summer,","",124],["","so wearing warm clothes is a good idea.","",129.8],["","Thanks. I'm a little nervous, but I'm excited to try it.","",133.3]]},
{"id":"sb-23","u":23,"book":"Student's Book","title":"Interesting places and different cultures","dur":128,"audio":"audio/a2/student/unit-23.mp3","lines":[["","Good morning. World Travel Club. How can I help?","",6.4],["","Hi. I saw your poster about the International Culture Day and I'd like some information.","",10.2],["","Of course. Can I take your name first?","",16.6],["","Yes. I'm Lucy Warren.","",19.8],["","Could you spell your surname, please?","",22.7],["","Sure. It's W-A-R-R-E-N.","",25.4],["","Thank you. Culture Day is a chance to learn about different countries through food, music, clothes and activities.","",30],["","This year, the main country is Japan.","",38],["","That's great! I've always wanted to visit there. What activities will you have?","",41],["","There are several. In the morning, a traveller will give a talk about Japanese cities and everyday life.","",47],["","It starts at 10.30 in the main hall.","",54],["","That sounds interesting. I'd like to hear about what daily life is really like there.","",57],["","After the talk, there's a short language lesson. You can learn some simple greetings and useful words.","",63],["","Nice. What happens in the afternoon?","",70],["","At one o'clock, there's a cooking demonstration. The chef will show visitors how to prepare a traditional rice dish. Everyone can taste it afterwards.","",73],["","afterwards.","",83],["","Excellent! I love trying food from other countries.","",84],["","There's also a display of traditional clothes. Some visitors can try them on and take photographs.","",88],["","Do you have any music?","",95],["","Yes. A group of musicians will perform at three. They use traditional drums so the performance can be quite loud.","",97],["","Sounds fun! How much does Culture Day cost?","",105],["","Adult tickets are normally £12, but students pay £8 if they bring a student card.","",110],["","Perfect! I'm a student. Where is the event?","",116.3],["","At the International Centre on Park Street, opposite the Museum.","",120.7],["","Great! I'll definitely come.","",124.8]]},
{"id":"sb-24","u":24,"book":"Student's Book","title":"Life in the past and life today","dur":130,"audio":"audio/a2/student/unit-24.mp3","lines":[["","Welcome to Then and Now. Today we're talking about how everyday life has changed.","",6.2],["","Could you introduce yourself? Of course. I'm Margaret Hill.","",12.2],["","Could you spell your surname, please? Yes, it's H-I-L-L.","",17.3],["","Thank you. Margaret, where did you grow up?","",24.6],["","I grew up in a small village. There were only a few shops and everybody seemed to know each other.","",27.8],["","How did you usually get to school?","",34.5],["","I normally walked. The school was about two kilometres from our house.","",37.1],["","My brother and I went together, even when the weather was bad.","",42.3],["","Did your family have a television?","",46.2],["","Yes, but only one. We got our first television when I was about ten.","",49.1],["","It was quite small and there weren't many programs to choose from.","",55],["","That's very different from today. What did you do for entertainment?","",60],["","We spent much more time outside. After school we played games in the street or rode our bikes.","",65],["","In the evening I often read books or listened to the radio.","",72],["","What about shopping?","",76],["","My mother went to the local shops almost every day because we didn't have a big fridge.","",78],["","There was no supermarket nearby.","",84],["","Today I usually go shopping only once a week.","",87.2],["","How did people keep in touch with friends and family?","",91.3],["","We wrote letters or used the telephone at home.","",94.9],["","Calls were quite expensive so we didn't stay on the phone for very long.","",98.7],["","Which do you prefer?","",103.5],["","Life then or life today?","",105],["","Some things were nicer in the past because people spent more time together, but everyday","",108],["","life is certainly easier today. I can speak to my grandchildren online, buy things from","",113.2],["","home and find information in seconds.","",118.8],["","So technology has made a big difference.","",122.7],["","Definitely. I wouldn't want to give up the internet now.","",125.8]]},
{"id":"wb-01","u":1,"book":"Workbook","title":"Daily routines and habits","dur":129,"audio":"audio/a2/workbook/unit-01.mp3","lines":[["Interviewer","Hello. I'm asking people about their daily habits for our college project. Could I ask you some questions?","Salom. Kollej loyihamiz uchun odamlardan kundalik odatlari haqida soʻrayapman. Bir nechta savol bersam boʻladimi?",5.3],["Daniel","Of course.","Albatta.",12.6],["Interviewer","Thanks. First, what's your name?","Rahmat. Avval, ismingiz nima?",13.9],["Daniel","I'm Daniel Brooks.","Men Daniel Brooks.",17.7],["Interviewer","And could you spell your surname for me?","Familiyangizni harflab bera olasizmi?",19.8],["Daniel","Yes, it's B-R-O-O-K-S.","Ha, B-R-O-O-K-S.",22.7],["Interviewer","Great. Let's start with your morning routine. Do you get up early?","Zoʻr. Ertalabki tartibingizdan boshlaylik. Erta turasizmi?",27.8],["Daniel","Yes, because I start work quite early. My alarm rings at 6.20 and I usually get up 10 minutes later at 6.30. I wash my face, get dressed and then make breakfast.","Ha, chunki ishni ancha erta boshlayman. Budilnik 6.20 da chaladi, men odatda 10 daqiqadan keyin, 6.30 da turaman. Yuzimni yuvaman, kiyinaman va nonushta tayyorlayman.",33.3],["Interviewer","What do you normally have?","Odatda nima yeysiz?",46.4],["Daniel","I usually have toast with cheese. I sometimes have eggs at the weekend, but they take too long on work days. I always drink a glass of juice with breakfast.","Odatda pishloqli tost yeyman. Dam olish kunlari baʼzan tuxum yeyman, lekin ish kunlari u juda uzoq pishadi. Nonushtada doim bir stakan sharbat ichaman.",48.5],["Interviewer","How do you get to work?","Ishga qanday borasiz?",59.5],["Daniel","I usually cycle. I bought a new bicycle last year and I really enjoy riding it. If the weather is bad, I take the bus instead.","Odatda velosipedda boraman. Oʻtgan yili yangi velosiped sotib oldim va unda yurishni juda yaxshi koʻraman. Ob-havo yomon boʻlsa, oʻrniga avtobusga chiqaman.",61.6],["Interviewer","And what time do you start work?","Ishni soat nechada boshlaysiz?",70.8],["Daniel","At 8 o'clock. I work in a small hotel so mornings can be quite busy. I have lunch at about 12.30, usually in the staff room.","Soat 8 da. Kichik mehmonxonada ishlayman, shuning uchun ertalablari ancha band boʻladi. Tushlikni taxminan 12.30 da, odatda xodimlar xonasida qilaman.",73.4],["Interviewer","What do you do when you finish work?","Ishdan keyin nima qilasiz?",83.4],["Daniel","I finish at 4. On Thursdays, I meet my brother and we play tennis in the park. On other weekdays, I normally go home and relax.","Soat 4 da tugataman. Payshanba kunlari akam bilan uchrashamiz va bogʻda tennis oʻynaymiz. Boshqa ish kunlari odatda uyga borib dam olaman.",85.9],["Interviewer","Do you cook in the evening?","Kechqurun ovqat pishirasizmi?",95.3],["Daniel","Most days. I usually make something simple because I don't like spending hours in the kitchen. After dinner, I often listen to music or watch a film.","Koʻp kunlari. Odatda oddiy narsa tayyorlayman, chunki oshxonada soatlab vaqt oʻtkazishni yoqtirmayman. Kechki ovqatdan keyin koʻpincha musiqa tinglayman yoki film koʻraman.",97.6],["Interviewer","What about bedtime?","Uxlash vaqti-chi?",108.1],["Daniel","I usually go to bed at 10.30, but I don't fall asleep immediately. I normally read a few pages of a book first.","Odatda soat 10.30 da yotaman, lekin darrov uxlab qolmayman. Avval odatda kitobdan bir necha sahifa oʻqiyman.",110.2],["Interviewer","And do you follow the same routine at weekends?","Dam olish kunlari ham shu tartibga amal qilasizmi?",118.7],["Daniel","Not at all. On Sunday mornings, I sleep longer and usually go for a walk after breakfast.","Aslo. Yakshanba kunlari ertalab koʻproq uxlayman va odatda nonushtadan keyin sayr qilaman.",122.3]],"q":[{"t":"What time does Daniel get up?","o":["6.20","6.30","7.30"],"a":1,"why":"Budilnik 6.20 da chaladi, lekin u 10 daqiqadan keyin turadi."},{"t":"How does Daniel go to work when the weather is bad?","o":["He takes the bus.","He walks.","He drives."],"a":0},{"t":"What does Daniel do on Thursdays after work?","o":["He cooks dinner.","He goes for a walk.","He plays tennis with his brother."],"a":2},{"t":"What time does Daniel finish work?","o":["12.30","4 o'clock","10.30"],"a":1},{"t":"What does Daniel do before he goes to sleep?","o":["He reads a few pages of a book.","He listens to music.","He plays tennis."],"a":0}]},
{"id":"wb-02","u":2,"book":"Workbook","title":"Family, Friends and Relationships","dur":129,"audio":"audio/a2/workbook/unit-02.mp3","lines":[["Interviewer","Hello. I'm doing a short project about the people who are important in our lives. Would you mind answering a few questions?","Salom. Men hayotimizdagi muhim insonlar haqida qisqa loyiha qilyapman. Bir nechta savolga javob berasizmi?",6.1],["Oliver","No, that's fine.","Yoʻq, mayli.",13.5],["Interviewer","Thanks. Let's start with your name.","Rahmat. Ismingizdan boshlaylik.",16.3],["Oliver","I'm Oliver Reed.","Men Oliver Reed.",18.5],["Interviewer","Is that R-E-A-D?","Bu R-E-A-D mi?",21.6],["Oliver","No, it's R-E-E-D.","Yoʻq, R-E-E-D.",24],["Interviewer","Got it. Now, Oliver, who do you live with?","Tushunarli. Endi, Oliver, kim bilan yashaysiz?",26.9],["Oliver","I live with my mum, my dad and my older sister, Hannah. She's 23. She used to live away from home when she was at university, but she moved back last summer.","Onam, dadam va katta opam Hannah bilan yashayman. U 23 yoshda. Universitetda oʻqiyotganida uydan uzoqda yashagan, lekin oʻtgan yozda qaytib kelgan.",32.2],["Interviewer","Do you and Hannah get on well?","Siz va Hannah inoq yashaysizlarmi?",43.2],["Oliver","Most of the time. She's very helpful, and I can talk to her when I have a problem. We have different interests, though. She loves reading, while I prefer playing computer games.","Koʻpincha ha. U juda yordamchi, muammom boʻlsa u bilan gaplasha olaman. Lekin qiziqishlarimiz boshqa. U kitob oʻqishni yaxshi koʻradi, men esa kompyuter oʻyinlarini afzal koʻraman.",45.7],["Interviewer","Do you do anything together?","Birga biror ish qilasizlarmi?",57.2],["Oliver","Yes. We both enjoy cooking, so on Sunday evenings we usually make dinner for our parents. Last Sunday we made chicken and rice.","Ha. Ikkalamiz ham ovqat pishirishni yaxshi koʻramiz, shuning uchun yakshanba kechqurunlari odatda ota-onamizga kechki ovqat tayyorlaymiz. Oʻtgan yakshanba tovuq va guruch pishirdik.",59.7],["Interviewer","Is there anyone else in your family you see regularly?","Oilangizda muntazam koʻrishadigan yana kim bor?",68.9],["Oliver","My uncle lives nearby. He has two young children, so I sometimes look after them. I usually help on Friday afternoons when he's still at work.","Amakim yaqin atrofda yashaydi. Uning ikkita kichik farzandi bor, shuning uchun baʼzan ularga qarab turaman. Odatda juma kunlari tushdan keyin, u hali ishda boʻlganida yordam beraman.",72.6],["Interviewer","Now, tell me about your friends.","Endi doʻstlaringiz haqida gapirib bering.",82.4],["Oliver","My closest friend is Sam. We first met at a football club about six years ago. He doesn't play football anymore, but we still spend a lot of time together.","Eng yaqin doʻstim Sam. Biz birinchi marta taxminan olti yil oldin futbol klubida uchrashganmiz. U endi futbol oʻynamaydi, lekin biz hali ham koʻp vaqt birga oʻtkazamiz.",85.3],["Interviewer","What's Sam like?","Sam qanday inson?",95.7],["Oliver","He's quiet when you first meet him, but he's very kind. He's also patient, which is useful because I'm sometimes a little impatient.","Dastlab tanishganda u jim, lekin juda mehribon. U sabrli ham, bu foydali, chunki men baʼzan sal sabrsizman.",97.5],["Interviewer","How often do you see him?","Uni qanchalik tez-tez koʻrasiz?",107.1],["Oliver","Usually twice a week. We meet at the library on Wednesday because we're both studying for exams. At the weekend, we sometimes play basketball or go out for lunch.","Odatda haftada ikki marta. Chorshanba kuni kutubxonada uchrashamiz, chunki ikkalamiz ham imtihonlarga tayyorlanyapmiz. Dam olish kunlari baʼzan basketbol oʻynaymiz yoki tushlik qilgani chiqamiz.",109.4],["Interviewer","And how do you keep in touch on other days?","Boshqa kunlari qanday aloqada boʻlasizlar?",120.2],["Oliver","Mostly by text. We rarely phone each other because messaging is easier.","Asosan xabar orqali. Bir-birimizga kamdan-kam qoʻngʻiroq qilamiz, chunki xabar yozish osonroq.",123.2]],"q":[{"t":"How old is Oliver's sister, Hannah?","o":["20","23","32"],"a":1},{"t":"When does Oliver usually help his uncle?","o":["On Friday afternoons","On Sunday evenings","On Wednesday evenings"],"a":0},{"t":"Where did Oliver and Sam first meet?","o":["At the library","At university","At a football club"],"a":2},{"t":"Why do Oliver and Sam meet at the library on Wednesday?","o":["They play basketball there.","They are studying for exams.","They have lunch there."],"a":1,"why":"Ular imtihonlarga tayyorlanishadi."},{"t":"How do Oliver and Sam usually keep in touch?","o":["By text","By phone","By email"],"a":0}]},
{"id":"wb-03","u":3,"book":"Workbook","title":"Hobbies and Free Time","dur":132,"audio":"audio/a2/workbook/unit-03.mp3","lines":[["Interviewer","Hello, I'm asking students about their hobbies for our college website. Can I ask you a few questions?","Salom, men kollejimiz veb-sayti uchun talabalardan hobbilari haqida soʻrayapman. Bir nechta savol bersam boʻladimi?",4.8],["Leo","Sure.","Albatta.",12.5],["Interviewer","Thanks. Can I start with your name?","Rahmat. Ismingizdan boshlasam boʻladimi?",13.8],["Leo","Yes, I'm Leo Martin.","Ha, men Leo Martin.",17.4],["Interviewer","Sorry, how do you spell your surname?","Kechirasiz, familiyangiz qanday yoziladi?",20.5],["Leo","It's M-A-R-T-I-N.","M-A-R-T-I-N.",23.6],["Interviewer","Thank you. So, Leo, what do you usually do when you have some free time?","Rahmat. Xoʻsh, Leo, boʻsh vaqtingiz boʻlsa odatda nima qilasiz?",27.3],["Leo","I really enjoy being outdoors. My main hobby is cycling. I sometimes ride around town, but at weekends I prefer going into the countryside because the roads are quieter.","Men tashqarida boʻlishni juda yaxshi koʻraman. Asosiy hobbim velosiped haydash. Baʼzan shahar boʻylab haydayman, lekin dam olish kunlari qishloqqa chiqishni afzal koʻraman, chunki yoʻllar tinchroq.",34.5],["Interviewer","Do you go cycling every weekend?","Har dam olish kuni velosiped haydaysizmi?",46.6],["Leo","Almost. I normally go on Sunday morning. I used to go on Saturdays, but I started working at a café on Saturday mornings about three months ago.","Deyarli. Odatda yakshanba ertalab chiqaman. Oldin shanba kunlari chiqardim, lekin taxminan uch oy oldin shanba ertalablari kafeda ishlay boshladim.",49.3],["Interviewer","Do you cycle alone?","Yolgʻiz haydaysizmi?",59.5],["Leo","Sometimes, but I usually go with my cousin. We leave home quite early, usually at about 8.30, because there aren't many cars on the road then. We normally ride for two hours and stop somewhere for a drink.","Baʼzan, lekin odatda amakivachcham bilan boraman. Uydan ancha erta, odatda soat 8.30 atrofida chiqamiz, chunki u payt yoʻlda mashina kam boʻladi. Odatda ikki soat haydaymiz va biror joyda ichimlik ichish uchun toʻxtaymiz.",61.7],["Interviewer","What do you do when the weather is bad?","Ob-havo yomon boʻlsa nima qilasiz?",75.9],["Leo","Then I stay indoors. I'm learning to play the guitar at the moment. I'm still a beginner, so I practice simple songs. I try to practice several times during the week.","Unda uyda qolaman. Hozir gitara chalishni oʻrganyapman. Hali boshlovchiman, shuning uchun oddiy qoʻshiqlarni mashq qilaman. Hafta davomida bir necha marta mashq qilishga harakat qilaman.",78.7],["Interviewer","Do you have any other hobbies?","Yana boshqa hobbilaringiz bormi?",90.2],["Leo","Yes. I like playing chess. There's a small club at my college, and we meet every Wednesday after classes. I'm not the best player there, but it's fun, and I'm getting better.","Ha. Shaxmat oʻynashni yaxshi koʻraman. Kollejimizda kichik klub bor, har chorshanba darsdan keyin yigʻilamiz. Men u yerdagi eng yaxshi oʻyinchi emasman, lekin qiziq va yaxshilanib boryapman.",92.6],["Interviewer","How do you usually relax in the evening?","Kechqurun odatda qanday dam olasiz?",104.4],["Leo","I sometimes watch films, but I spend more time listening to podcasts. I like ones about travel, because I enjoy learning about different countries.","Baʼzan film koʻraman, lekin koʻproq vaqtimni podkastlar tinglashga sarflayman. Sayohat haqidagilarini yoqtiraman, chunki turli davlatlar haqida bilishni yaxshi koʻraman.",107.7],["Interviewer","Is there a hobby you'd like to try in the future?","Kelajakda sinab koʻrmoqchi boʻlgan hobbingiz bormi?",117.5],["Leo","I'd like to try fishing. My uncle goes quite often, and he says he'll take me with him this summer.","Baliq ovlashni sinab koʻrmoqchiman. Amakim ancha tez-tez boradi va bu yozda meni ham olib ketishini aytdi.",121.2],["Interviewer","Great. Thanks, Leo.","Zoʻr. Rahmat, Leo.",127.8],["Leo","No problem.","Arzimaydi.",130.1]],"q":[{"t":"Why does Leo cycle on Sunday now, not on Saturday?","o":["He plays chess on Saturdays.","He works at a café on Saturday mornings.","The roads are busy on Saturdays."],"a":1,"why":"U shanba ertalablari kafeda ishlaydi."},{"t":"What time do Leo and his cousin usually leave home?","o":["About 8.30","About 7.30","About 9.30"],"a":0},{"t":"When does the chess club meet?","o":["On Sunday mornings","On Saturday afternoons","On Wednesdays after classes"],"a":2},{"t":"What kind of podcasts does Leo like?","o":["About music","About travel","About sport"],"a":1},{"t":"Who will take Leo fishing this summer?","o":["His uncle","His cousin","His friend"],"a":0}]},
{"id":"wb-04","u":4,"book":"Workbook","title":"Food, Cooking and Eating","dur":138,"audio":"audio/a2/workbook/unit-04.mp3","lines":[["Interviewer","Hi, I'm collecting information about how people cook and eat at home. Could I ask you a few questions?","Salom, men odamlar uyda qanday ovqat pishirishi va yeyishi haqida maʼlumot yigʻyapman. Bir nechta savol bersam boʻladimi?",5.5],["Adam","Sure.","Albatta.",12.5],["Interviewer","Thanks. Can I have your name first?","Rahmat. Avval ismingizni aytsangiz.",14.6],["Adam","Yes, I'm Adam Foster.","Ha, men Adam Foster.",17],["Interviewer","Sorry, could you spell your surname?","Kechirasiz, familiyangizni harflab bera olasizmi?",21.3],["Adam","Of course, it's F-O-S-T-E-R.","Albatta, F-O-S-T-E-R.",24],["Interviewer","Great. Adam, do you usually have a big breakfast?","Zoʻr. Adam, odatda toʻyimli nonushta qilasizmi?",28.5],["Adam","Not really. I'm often in a hurry in the morning. I used to eat just a banana, but these days I normally make toast and have it with some cheese. I drink a glass of water too.","Unchalik emas. Ertalab koʻpincha shoshaman. Oldin faqat banan yer edim, lekin hozir odatda tost qilib, uni pishloq bilan yeyman. Bir stakan suv ham ichaman.",34.6],["Interviewer","What about lunch? Do you cook something?","Tushlik-chi? Biror narsa pishirasizmi?",46.4],["Adam","No, because I'm at college during the day. There's a café next to the library. I usually buy lunch there at about one o'clock. The sandwiches are good, but I normally choose soup because it's cheaper.","Yoʻq, chunki kunduzi kollejdaman. Kutubxona yonida kafe bor. Tushlikni odatda u yerdan soat birlarda sotib olaman. Sendvichlar yaxshi, lekin odatda shoʻrva tanlayman, chunki arzonroq.",49.9],["Interviewer","How much does lunch usually cost?","Tushlik odatda qancha turadi?",62.2],["Adam","The soup used to be £4, but it went up recently. It now costs £5. A sandwich is about £6, so I still save some money.","Shoʻrva oldin £4 edi, lekin yaqinda qimmatlashdi. Hozir £5 turadi. Sendvich taxminan £6, shuning uchun baribir biroz pul tejayman.",65.1],["Interviewer","Do you cook in the evening?","Kechqurun ovqat pishirasizmi?",75.3],["Adam","Yes. I share a flat with my friend Ben, and we take turns cooking. I cook on Mondays, Wednesdays and Saturdays. Ben cooks on the other days.","Ha. Doʻstim Ben bilan bitta kvartirada turaman va navbatma-navbat ovqat pishiramiz. Men dushanba, chorshanba va shanba kunlari pishiraman. Qolgan kunlari Ben pishiradi.",77.6],["Interviewer","What are you good at making?","Nimani yaxshi pishirasiz?",88.2],["Adam","I make a really good masala. It's quite simple. I use potatoes, onions, tomatoes and some spices. Ben prefers my pasta, but curry is my favourite.","Men juda yaxshi masala pishiraman. Bu ancha oddiy. Kartoshka, piyoz, pomidor va bir oz ziravorlar ishlataman. Ben mening pastamni afzal koʻradi, lekin eng yaxshi koʻrganim karri.",90.4],["Interviewer","Do you ever invite people for dinner?","Hech kimni kechki ovqatga taklif qilasizmi?",102.6],["Adam","Sometimes. We usually invite a few friends once a month. Everyone brings something, so we don't have to prepare all the food ourselves.","Baʼzan. Odatda oyda bir marta bir necha doʻstimizni taklif qilamiz. Hamma nimadir olib keladi, shuning uchun hamma ovqatni oʻzimiz tayyorlamaymiz.",105.4],["Interviewer","What do you usually bring when someone else invites you?","Boshqalar sizni taklif qilganda odatda nima olib borasiz?",114.2],["Adam","I normally bring juice or something sweet. I'm terrible at making desserts, so I usually buy them from a shop.","Odatda sharbat yoki biror shirinlik olib boraman. Desert tayyorlashni umuman bilmayman, shuning uchun odatda doʻkondan sotib olaman.",118.2],["Interviewer","Is there anything you want to learn to cook?","Pishirishni oʻrganmoqchi boʻlgan narsangiz bormi?",125.7],["Adam","Yes. Bread. My grandmother makes amazing bread, and I'd like her to teach me.","Ha. Non. Buvim ajoyib non yopadi va u menga oʻrgatishini xohlayman.",128.6],["Interviewer","Great. Thanks for your time.","Zoʻr. Vaqtingiz uchun rahmat.",135]],"q":[{"t":"What does Adam usually have for breakfast these days?","o":["Toast with cheese","Just a banana","Cereal and tea"],"a":0,"why":"Oldin faqat banan yer edi, hozir tost va pishloq."},{"t":"How much does the soup cost now?","o":["£4","£6","£5"],"a":2},{"t":"On which days does Adam cook?","o":["Tuesdays, Thursdays and Sundays","Mondays, Wednesdays and Saturdays","Mondays, Fridays and Sundays"],"a":1},{"t":"What does Adam usually bring when someone invites him for dinner?","o":["Juice or something sweet","Bread","Homemade desserts"],"a":0,"why":"U desert tayyorlashni bilmaydi, shuning uchun sotib oladi."},{"t":"Who does Adam want to learn to make bread from?","o":["His friend Ben","His mother","His grandmother"],"a":2}]},
{"id":"wb-05","u":5,"book":"Workbook","title":"Shopping and money","dur":127,"audio":"audio/a2/workbook/unit-05.mp3","lines":[["Receptionist","Good morning. Green Street Market. How can I help?","Xayrli tong. Green Street bozori. Sizga qanday yordam bera olaman?",4.7],["Rachel","Hi. I'm calling about the weekend market. I'd like to sell some things there on Saturday.","Salom. Men dam olish kunlaridagi bozor haqida qoʻngʻiroq qilyapman. Shanba kuni u yerda baʼzi narsalarni sotmoqchiman.",8.5],["Receptionist","Of course. I just need to take a few details. What's your name?","Albatta. Bir nechta maʼlumotni yozib olishim kerak. Ismingiz nima?",15],["Rachel","Rachel King.","Rachel King.",20.4],["Receptionist","Could you spell your surname, please?","Familiyangizni harflab bera olasizmi?",21.9],["Rachel","Yes. It's K-I-N-G.","Ha. K-I-N-G.",24.7],["Receptionist","Thank you. And what are you planning to sell?","Rahmat. Nima sotmoqchisiz?",29.4],["Rachel","Mostly clothes. I have some jackets and t-shirts that I don't wear anymore. I also have a few books, but I think clothes will be the main thing.","Asosan kiyim. Endi kiymaydigan bir nechta kurtka va futbolkam bor. Bir nechta kitobim ham bor, lekin asosiysi kiyim boʻladi deb oʻylayman.",33.3],["Receptionist","That's fine. You'll need to rent a table. We have small and large ones available.","Yaxshi. Stol ijaraga olishingiz kerak. Kichik va katta stollarimiz bor.",43.7],["Rachel","How much are they?","Ular qancha turadi?",50.4],["Receptionist","A large table is £15 for the day. The small one used to cost £8, but from this month,","Katta stol bir kunga £15. Kichigi avval £8 turardi, lekin shu oydan boshlab",52.1],["Rachel","it's £10. I think the small one will be enough.","£10 boʻldi. Menimcha, kichigi yetarli boʻladi.",59.4],["Receptionist","OK. The market opens to customers at 10, but sellers need to arrive earlier. Please be there by 9.15, so you have time to prepare your table.","Xoʻp. Bozor xaridorlar uchun soat 10 da ochiladi, lekin sotuvchilar barvaqt kelishi kerak. Iltimos, stolingizni tayyorlashga vaqt boʻlishi uchun 9.15 gacha keling.",64.4],["Rachel","That's fine. Where exactly is the market?","Mayli. Bozor aynan qayerda?",75.5],["Receptionist","It's in Green Street Hall. Do you know the building?","Green Street Hall ichida. Bu binoni bilasizmi?",79],["Rachel","I know Green Street, but I'm not sure about the hall.","Green Street koʻchasini bilaman, lekin zalni aniq bilmayman.",83],["Receptionist","It's opposite the bank. There's a café on one side and a pharmacy on the other, so it's quite easy to find.","U bankning roʻparasida. Bir tomonida kafe, ikkinchi tomonida dorixona bor, shuning uchun topish ancha oson.",87.3],["Rachel","Great. Can customers pay by card?","Zoʻr. Xaridorlar karta bilan toʻlay oladimi?",95.4],["Receptionist","Some sellers accept cards, but you would need your own card machine. Most people bring cash, especially for cheaper things.","Baʼzi sotuvchilar karta qabul qiladi, lekin buning uchun oʻzingizning karta terminalingiz boʻlishi kerak. Koʻpchilik naqd pul olib keladi, ayniqsa arzonroq narsalar uchun.",98.7],["Rachel","OK. I'll remember that.","Xoʻp. Buni eslab qolaman.",107.4],["Receptionist","One more thing. Sellers must bring their own bags for customers. We provide the tables and chairs, but not bags.","Yana bir narsa. Sotuvchilar xaridorlar uchun oʻzlarining xaltalarini olib kelishi kerak. Stol va stullarni biz beramiz, xalta esa yoʻq.",109.8],["Rachel","No problem. I have plenty at home.","Muammo yoʻq. Uyda juda koʻp bor.",118.4],["Receptionist","Excellent. We'll see you on Saturday.","Ajoyib. Shanba kuni koʻrishamiz.",121.5],["Rachel","Thanks. Bye.","Rahmat. Xayr.",124.8]],"q":[{"t":"What time must sellers arrive at the market?","o":["At 9","At 9.15","At 10"],"a":1,"why":"Xaridorlar 10 da kiradi, sotuvchilar 9.15 gacha kelishi kerak."},{"t":"How much is a small table now?","o":["£10","£8","£15"],"a":0,"why":"£8 eski narx, shu oydan £10 boʻldi."},{"t":"Where is Green Street Hall?","o":["Opposite the pharmacy","Opposite the café","Opposite the bank"],"a":2},{"t":"What must sellers bring themselves?","o":["Bags for customers","Tables","Chairs"],"a":0},{"t":"How do most people pay at the market?","o":["By card","With cash","By phone"],"a":1}]},
{"id":"wb-06","u":6,"book":"Workbook","title":"School, Learning and Study","dur":132,"audio":"audio/a2/workbook/unit-06.mp3","lines":[["Receptionist","Hello, City Study Centre, how can I help?","Salom, City Study Centre, sizga qanday yordam bera olaman?",4.3],["Marcus","Hi, I'm interested in your weekend computer course. I saw a poster about it at my college.","Salom, men sizlarning dam olish kunlaridagi kompyuter kursingizga qiziqyapman. Bu haqda kollejimizda plakat koʻrdim.",9.1],["Receptionist","Certainly, I can give you some information. First, can I take your name?","Albatta, sizga maʼlumot bera olaman. Avval ismingizni aytsangiz.",15],["Marcus","Yes, it's Marcus Hill.","Ha, men Marcus Hill.",21.4],["Receptionist","Could you spell your surname?","Familiyangizni harflab bera olasizmi?",24.6],["Marcus","Of course, it's H-I-L-L.","Albatta, H-I-L-L.",27],["Receptionist","Thanks. Have you done a computer course before?","Rahmat. Avval kompyuter kursida oʻqiganmisiz?",32.5],["Marcus","No, but I use a computer every day for my studies. I can type and find information online, but I'd like to learn more.","Yoʻq, lekin oʻqishim uchun har kuni kompyuterdan foydalanaman. Matn terishni va internetdan maʼlumot topishni bilaman, lekin koʻproq oʻrganmoqchiman.",36.5],["Receptionist","Then the beginner course should be suitable. Classes are on Saturday mornings. We used to have a Sunday class too, but that isn't running this term.","Unda boshlangʻich kurs mos boʻlsa kerak. Darslar shanba kuni ertalab boʻladi. Avval yakshanba kuni ham dars bor edi, lekin bu semestrda u ochilmayapti.",45.7],["Marcus","Saturday is perfect. What time does it start?","Shanba juda yaxshi. Soat nechada boshlanadi?",55.8],["Receptionist","The building opens at 9, but the lesson begins at 9.30. Each lesson lasts two hours.","Bino soat 9 da ochiladi, lekin dars 9.30 da boshlanadi. Har bir dars ikki soat davom etadi.",59.7],["Marcus","OK, what do students learn?","Xoʻp, oʻquvchilar nimalarni oʻrganadi?",67.2],["Receptionist","During the first few weeks, you'll learn how to create documents and organise files. Later, you'll learn to make simple presentations. There's also a lesson about using the internet safely.","Dastlabki bir necha haftada hujjatlar yaratish va fayllarni tartibga solishni oʻrganasiz. Keyinroq oddiy taqdimotlar yasashni oʻrganasiz. Internetdan xavfsiz foydalanish haqida ham dars bor.",70.2],["Marcus","That sounds useful. Do I need to bring my own computer?","Bu foydali ekan. Oʻz kompyuterimni olib kelishim kerakmi?",83.2],["Receptionist","No. Every student can use one of our computers. You should bring a notebook though, because the teacher gives lots of useful tips.","Yoʻq. Har bir oʻquvchi bizning kompyuterlarimizdan birini ishlatishi mumkin. Lekin daftar olib kelganingiz yaxshi, chunki oʻqituvchi juda koʻp foydali maslahatlar beradi.",87.4],["Marcus","Fine. How much is the course?","Yaxshi. Kurs qancha turadi?",96.5],["Receptionist","The full course is £75. It was £85 last term, so it's a little cheaper now.","Toʻliq kurs £75. Oʻtgan semestrda £85 edi, shuning uchun hozir biroz arzonroq.",99.3],["Marcus","Good. Where exactly is the study centre?","Yaxshi. Oʻquv markazi aynan qayerda?",107.5],["Receptionist","We're on King Road, opposite the library. Your lessons will be in room 8, which is on the first floor.","Biz King Road koʻchasida, kutubxonaning roʻparasidamiz. Darslaringiz 8-xonada boʻladi, u birinchi qavatda.",111],["Marcus","Great. Can I register online?","Zoʻr. Onlayn roʻyxatdan oʻta olamanmi?",118.2],["Receptionist","Yes. Or you can come to the centre and complete a form here.","Ha. Yoki markazga kelib, shu yerda anketa toʻldirishingiz mumkin.",121.1],["Marcus","I think I'll do it online tonight.","Menimcha, bugun kechqurun onlayn qilaman.",126.4],["Receptionist","Perfect. We hope to see you soon.","Ajoyib. Tez orada koʻrishamiz degan umiddamiz.",128.9]],"q":[{"t":"What time does the lesson begin?","o":["At 9.00","At 9.15","At 9.30"],"a":2,"why":"Bino 9 da ochiladi, dars 9.30 da boshlanadi."},{"t":"How long is each lesson?","o":["One hour","Two hours","Three hours"],"a":1},{"t":"What should Marcus bring to the lessons?","o":["A notebook","A computer","A poster"],"a":0},{"t":"How much is the full course now?","o":["£85","£75","£65"],"a":1,"why":"£85 oʻtgan semestrdagi narx edi."},{"t":"Where will the lessons be?","o":["Room 8 on the first floor","Room 8 on the second floor","Room 18 on the first floor"],"a":0}]},
{"id":"wb-07","u":7,"book":"Workbook","title":"Jobs and Working Life","dur":130,"audio":"audio/a2/workbook/unit-07.mp3","lines":[["","Good afternoon. Bright office services. How can I help?","",5.1],["","Hi. I'm calling about the part-time office job you advertised.","",9.2],["","Of course. Can I take your name first?","",13.8],["","Yes. It's Maya Evans.","",17.2],["","Could you spell your surname, please?","",20.3],["","Sure. It's E-V-A-N-S.","",23.1],["","Thank you. The job is for an office assistant. Have you done office work before?","",28],["","A little. Last year I worked in my uncle's business for two months. I answered emails,","",34],["","organised papers and sometimes spoke to customers on the phone.","",40.6],["","Good. Being organised is very important here because we have a lot of documents and customer","",45.2],["","information. That's fine. I like keeping things in the right place.","",50.9],["","Excellent. The job is three days a week. Monday, Wednesday and Friday. On Mondays and Fridays,","",56.6],["","you start at nine, but on Wednesday you start at ten o'clock because we have a staff meeting first.","",63.7],["","That works well for me. What would I usually do during the day?","",70.3],["","Mostly answer emails and prepare documents. You'll also take messages when customers phone.","",75],["","Sometimes we'll ask you to make copies of documents for meetings.","",81.4],["","Okay. Do I need to wear anything special?","",85.7],["","Nothing too formal. A shirt or smart top is fine,","",89.6],["","but please wear black shoes. Trainers aren't suitable in the office.","",93.6],["","No problem. How much do you pay?","",98.8],["","The starting rate is £12 an hour. After three months, it can increase if everything goes well.","",101.8],["","Great. How can I apply?","",108.4],["","Please bring your CV to the office. Ask for Mr Taylor at the front desk.","",111],["","He's interviewing applicants on Tuesday and Thursday this week.","",116.2],["","Thursday would be better for me.","",120.2],["","Perfect. Come any time between two and four.","",122.8],["","Thanks very much.","",126.8],["","You're welcome.","",128.8]]},
{"id":"wb-08","u":8,"book":"Workbook","title":"Travel and transport","dur":130,"audio":"audio/a2/workbook/unit-08.mp3","lines":[["","Good afternoon. Northside train station. How can I help?","",4.8],["","Hi. I'm travelling to Brighton tomorrow and I'd like some information about the trains.","",9.3],["","Certainly. Are you travelling in the morning or afternoon?","",15.6],["","In the morning. I need to be in Brighton before lunch time.","",20.1],["","No problem. Before I check the trains, could I take your name?","",24.6],["","Yes. It's Sarah Blake. Could you spell your surname for me?","",29.3],["","Of course. It's B-L-A-K-E. Thank you.","",34.8],["","Now, there's a train at 8.10 but that one stops at every station. The faster train leaves at 8.40.","",40.6],["","I'd prefer the faster one. Does it go directly to Brighton?","",48.6],["","Not quite. You need to change once at Greenford.","",53.4],["","Don't worry. You'll have about 20 minutes to get to the next train.","",57.4],["","That should be enough. How much is the ticket?","",61.4],["","A normal single ticket is £22. But if you have a student card, it's only £17.","",64.8],["","Great. I'm a student and I have my card with me.","",72.2],["","Perfect. Would you like to reserve a seat?","",76.1],["","Yes, please. I'd rather sit by the window if possible. I don't really like aisle seats.","",79.2],["","That's fine. There are still several window seats available.","",85.8],["","Great. Can I take my bicycle on the train?","",89.8],["","Yes, but there's only space for four bicycles,","",93.8],["","so you need to book a place for it before travelling.","",97.4],["","OK. Where should I go when I arrive at the station tomorrow?","",101],["","Your train normally leaves from Platform 5, but tomorrow it will leave from Platform 3","",105.8],["","because some work is being done near Platform 5.","",112],["","I'm glad I asked.","",115.7],["","Yes, it's always worth checking. Try to arrive about 15 minutes before departure.","",117.9],["","I will. Thanks for your help.","",124.2],["","You're welcome. Have a good journey.","",127.1]]},
{"id":"wb-09","u":9,"book":"Workbook","title":"Cities, Towns and Neighbourhoods","dur":139,"audio":"audio/a2/workbook/unit-09.mp3","lines":[["","Good morning, Hilltown Information Office. How can I help?","",5.5],["","Hi, my family and I are moving to Hilltown next month and I'd like to know more about the area.","",9.7],["","Of course, I can send you some information later. First, could I take your name?","",16.1],["","Yes, I'm David Palmer.","",22.2],["","Could you spell your surname, please?","",25.3],["","Sure, it's P-A-L-M-E-R.","",28.2],["","Thank you. Do you know which neighbourhood you're moving to?","",33.4],["","Yes, our new house is in Westwood. We chose it because my wife works nearby.","",37.7],["","That's a popular area for families. There's a primary school,","",43.8],["","several shops and a large playground.","",47.8],["","That sounds good. We have two young children. Is there a supermarket within walking distance?","",51],["","Yes, there are actually two. The larger one is on Station Road.","",57.5],["","It stays open until 10 o'clock every evening except Sunday.","",62.7],["","Excellent. What about public transport?","",67.3],["","Bus number 18 goes through Westwood.","",71],["","It stops outside the supermarket and then continues to the town centre.","",74],["","Is there a train station too?","",79],["","Yes, but it's on the other side of town.","",81.6],["","The easiest way to reach it is by bus. The journey from Westwood takes about 25 minutes.","",84.7],["","Okay, my children also enjoy being outdoors. Is there a park nearby?","",91.4],["","Yes, Oak Park is about a 15-minute walk away.","",97.6],["","It has a playground and a large lake. People often walk or cycle around it.","",101.4],["","Lovely. Is the neighbourhood generally quiet?","",107.4],["","During the week, yes. Station Road can get quite noisy on Saturday afternoons","",111.1],["","because many people come to do their shopping.","",117.1],["","That shouldn't be a problem. And is there a doctor near Westwood?","",120],["","Yes, the health centre is on Market Street next to the pharmacy.","",124.8],["","It's about 10 minutes away by bus.","",129.4],["","Great. That's all I needed. Thank you very much.","",132],["","You're welcome. I hope the move goes well.","",135.8]]},
{"id":"wb-10","u":10,"book":"Workbook","title":"Technology and everyday life","dur":134,"audio":"audio/a2/workbook/unit-10.mp3","lines":[["","Hello. Digital Skills Club. How can I help?","",4.2],["","Hi. I saw your poster at the library and I'd like to join one of your classes.","",9.2],["","Of course. I'll take some details first. What's your name?","",15],["","I'm Chloe Grant. Could you spell your surname, please?","",19.4],["","Yes, it's G-R-A-N-T.","",23.1],["","Thank you. We have several classes. What would you like help with?","",29.1],["","I can use my phone quite well, but I've just bought a new laptop and I'd like to learn how to use it better.","",34.1],["","Then, our everyday technology class might be right for you. Students learn how to organise files, use useful apps and keep their information safe online.","",41.1],["","That sounds useful. When is the class?","",52.1],["","We have one on Tuesday afternoon and another on Thursday evening.","",55.1],["","The evening class is more popular with people who work during the day.","",60.1],["","Thursday would be much better for me.","",64.1],["","Fine. It starts at 6.15.","",67.1],["","We ask students to arrive about 10 minutes early, so please be here by 6.05.","",70.1],["","No problem. Do I need to bring my own computer?","",76.1],["","You can, but you don't have to. We have computers here. However, please bring your phone because","",80.1],["","one part of the lesson is about connecting different devices.","",87.3],["","OK, how many people are usually in the class?","",91.2],["","The maximum is 12, but there are normally around 8. Small groups make it easier for the teacher","",95.6],["","to help everyone.","",101.7],["","Good, and how much does it cost?","",103.4],["","It's £8 for each class. You can pay online or at the centre when you arrive.","",107.3],["","Where exactly is the class held? We're inside the community centre on Park","",113.8],["","Road. Go through the main entrance and take the stairs to the first floor. The class is","",118.4],["","in Room 5. Great! Can I book a place now?","",123.9],["","Certainly. I'll add your name to Thursday's class.","",128.6],["","Thanks very much.","",132.8]]},
{"id":"wb-11","u":11,"book":"Workbook","title":"Health, exercise and sleep","dur":136,"audio":"audio/a2/workbook/unit-11.mp3","lines":[["","Good afternoon. Wellbeing centre. How can I help?","",5.8],["","Hi. I'd like some information about your healthy living programme.","",9.8],["","My friend joined last month and recommended it to me.","",14.3],["","Certainly. I'll take a few details first. What's your name?","",18.5],["","I'm Emma Norton. Could you spell your surname, please?","",23.1],["","Sure. It's N-O-R-T-O-N.","",27.8],["","Thank you. What would you most like to improve?","",33.8],["","Probably my sleep. I usually go to bed at about 11, but I sometimes lie awake for a long time.","",37.4],["","In the morning, I often feel sleepy, especially when I have to get up early for work.","",45.1],["","I see. Do you drink much coffee?","",51.3],["","I used to drink three cups a day, including one after dinner.","",54.6],["","Now I only have coffee in the morning, and I drink water with my evening meal.","",59.2],["","That's a good change. What about exercise?","",64.6],["","I go swimming once a week. I'd like to exercise more often, but I don't enjoy going to the gym.","",68.2],["","You could try our evening walking group. It meets twice a week.","",75.6],["","Tuesday's walk starts at seven, and the Thursday walk starts half an hour earlier.","",79.8],["","Thursday sounds good. How long do you walk for?","",85.1],["","About an hour. We normally meet outside the centre and walk through the park.","",88.9],["","Do I need to bring anything?","",94.3],["","Comfortable shoes are important. We also recommend bringing a bottle of water,","",96.4],["","especially when the weather is warm.","",101.5],["","Okay. And what time should I try to go to sleep?","",104.2],["","That depends on when you get up. You said you start work early. What time does your alarm ring?","",108.5],["","At 6.30.","",114.9],["","Then try to be asleep by around 10.30. Also, avoid looking at a screen for 30 minutes before","",116.8],["","bed. Reading a book can be a better way to relax.","",123.8],["","I can try that. I enjoy reading anyway.","",127.8],["","Excellent. Small changes can make a big difference.","",131.6]]},
{"id":"wb-12","u":12,"book":"Workbook","title":"Sports and competitions","dur":131,"audio":"audio/a2/workbook/unit-12.mp3","lines":[["","Hello, Riverside Sports Centre. How can I help?","",5],["","Hi. I'm calling about the running event next month. I'd like to enter.","",9],["","Certainly. I can complete the registration with you now. Can I have your name?","",14.8],["","Yes. I'm Hannah Cole.","",20.4],["","Could you spell your surname, please?","",23],["","Sure. It's C-O-L-E.","",26],["","Thank you. We have two races this year. A 5km race and a 10km race. Which would you like to enter?","",30],["","I thought about doing 10km, but I've only been running regularly for six months.","",39.1],["","I think the 5km race is better for me this time.","",45],["","Good choice. You can always try the longer one next year. The event is on Sunday 12th.","",49],["","The race itself begins at 11, but registration closes at 10.15.","",55],["","OK. I'll make sure I'm there before then.","",60.6],["","Good. Have you taken part in a running competition before?","",64.1],["","No. This will be my first one. I usually run in the park near my house three times a week.","",68.3],["","Great. The route is mostly through Riverside Park. There's one short hill near the middle,","",75.1],["","but the rest of the route is quite flat.","",81],["","That sounds fine. Do runners need to bring their own water?","",84],["","You can if you want, but we provide water at two points along the route.","",88.4],["","You should definitely bring a small towel for after the race.","",93.1],["","OK. How much does it cost to enter?","",97],["","It's normally £14, but students pay £10 if they show a student card.","",100.2],["","Perfect. I'm a student.","",106.5],["","Excellent. After the race, everyone gets a drink and some fruit.","",109],["","The first three runners also receive a prize.","",113.4],["","Where do I collect my race number?","",117],["","From the information desk inside the sports centre. It will be open from 9 o'clock.","",119.5],["","Great. Thanks for your help.","",125.1],["","You're welcome. Good luck with your training.","",127.7]]},
{"id":"wb-13","u":13,"book":"Workbook","title":"Weather and seasonal activities","dur":129,"audio":"audio/a2/workbook/unit-13.mp3","lines":[["","Hello, Mountain View Visitor Centre. How can I help you?","",5.8],["","Hi, I'm planning to visit Mountain View with some friends during the winter holiday.","",10.3],["","I'd like to know what activities are available.","",15.3],["","Certainly. Can I take your name first?","",18.4],["","Yes, I'm Peter Shaw.","",21.8],["","Could you spell your surname, please?","",24.7],["","Of course. It's S-H-A-W.","",27.4],["","Thank you. When are you planning to come?","",32.2],["","Next Friday. We were thinking about Saturday, but one of my friends has to work that day.","",35.6],["","Friday should be a good day. We had heavy snow earlier this week,","",41.9],["","so there are lots of winter activities available.","",46.1],["","Great. We'd really like to try skiing.","",49.4],["","The beginner ski lesson would be suitable. The morning lesson starts at nine,","",52.7],["","but that group is already full. There are still places in the afternoon lesson at 1.30.","",57.6],["","That's fine. None of us has skied before, so a lesson would be useful.","",63.6],["","Definitely. You can rent all the equipment here. We provide skis and boots,","",69],["","but everyone needs to bring their own gloves.","",74.4],["","Okay. What will the weather be like?","",77.6],["","It should stay dry, but it will be very cold.","",80.8],["","The temperature may fall to minus six degrees in the morning.","",84.6],["","We'll make sure we wear warm clothes. How much is the lesson?","",88.7],["","The lesson normally costs £25 per person.","",93],["","Because you're coming on a weekday, the price is only £20.","",97],["","Good. Is there anything to do after the lesson?","",101.4],["","Yes. You can go ice skating until seven o'clock or visit the cafe.","",105],["","They serve hot drinks, soup and sandwiches.","",110.3],["","The cafe sounds good after being outside all afternoon.","",113.9],["","I'm sure it will. Just remember that it gets dark early in winter,","",117.9],["","so don't start any long walks late in the day.","",122.6],["","Good advice. Thanks very much.","",126.2]]},
{"id":"wb-14","u":14,"book":"Workbook","title":"Animals and Wildlife","dur":134,"audio":"audio/a2/workbook/unit-14.mp3","lines":[["","Hello. Riverbank Animal Centre. How can I help?","",4.2],["","Hi. I saw some information online about helping at the centre and I'm interested in becoming a","",9.4],["","volunteer. That's great. We're always looking for people to help. Can I take your name first?","",15.9],["","Yes, I'm Sophie Lane. Could you spell your surname, please?","",23.6],["","Of course. It's L-A-N-E.","",28.3],["","Thank you. Have you worked with animals before?","",33.3],["","Not as a job, but my family has always had pets.","",37.3],["","We have two cats now and I used to look after my neighbour's dog when she was away.","",41.3],["","That's useful. Most new volunteers start by helping with the rabbits.","",46.3],["","They need fresh food, clean water and a clean living area every day.","",52.3],["","I'd be happy to do that. When do you need volunteers?","",57.3],["","We need the most help at weekends. Saturday morning is already quite busy, but we still need people on Sunday.","",61.3],["","Sunday is actually better for me. What time would I start?","",69.3],["","Volunteers usually arrive at 8.30. The centre opens to visitors at 10, so we try to finish most of the cleaning before then.","",74.3],["","OK. What should I wear?","",83.3],["","comfortable clothes are best. Please wear strong boots because some areas can","",86.3],["","get wet and muddy. Fine. Do volunteers work with the wild animals too? Not at","",91.2],["","first. We sometimes care for injured birds and other local wildlife but only","",98.4],["","experienced volunteers work closely with them. I understand. Is there any training?","",104.2],["","Yes, all new volunteers attend a short training session. The next one is on the 16th and lasts","",110.5],["","about two hours.","",118.3],["","Great! Is there anything I should bring to that?","",119.8],["","Just a notebook. We'll provide everything else.","",123.9],["","Perfect! I'd definitely like to join.","",127],["","Excellent! I'll add your name to the list.","",130.4]]},
{"id":"wb-15","u":15,"book":"Workbook","title":"Nature and the Environment","dur":131,"audio":"audio/a2/workbook/unit-15.mp3","lines":[["","Good afternoon. Green Community Centre, how can I help you?","",5.8],["","Hi, I saw a notice about your tree planting day and I'd like to take part.","",10.2],["","Wonderful. We still need a few more volunteers. Can I take your name?","",16.5],["","Yes, it's Laura Finch.","",21.8],["","Could you spell your surname please?","",24.6],["","Of course, it's F-I-N-C-H.","",27.4],["","Thank you. This time we're planting trees near the river. We planted some in the town park last year","",32.7],["","so we wanted to choose a different area.","",39.4],["","That sounds good. I cycle along the river sometimes and it would be nice to see more trees there.","",42.2],["","Exactly. The planting day is next Sunday. We normally organise these events on Saturdays","",49],["","but there's a big market in the area that day.","",55],["","Sunday works for me. When does it begin?","",58.5],["","We start at ten o'clock but please arrive by nine thirty. We need to put everyone into","",61.6],["","small groups and explain how to plant the trees correctly.","",67.1],["","Sure. Do I need any experience?","",71.4],["","Not at all. A team leader will show you what to do.","",74.8],["","We provide all the tools including gloves and small spades.","",78.2],["","Great. What should I wear?","",82.7],["","Old clothes are best. Please bring a jacket too. The forecast says it should stay dry","",85.6],["","but it may be cool near the water.","",91.8],["","Okay. How many trees are you hoping to plant?","",94.6],["","We originally planned to plant fifty but a local business gave us some extra trees.","",98.3],["","We now hope to plant seventy.","",103.8],["","Wow. That's quite a lot.","",106.6],["","It is but we already have nearly forty volunteers. We'll also stop for a short break at midday.","",109.5],["","Will there be food?","",117.1],["","We provide fruit and water. Please bring your own lunch though because the event","",118.8],["","continues until about three.","",123.1],["","No problem. I'll be there.","",125.8],["","Excellent. Thanks for helping us.","",128.1]]},
{"id":"wb-16","u":16,"book":"Workbook","title":"Films, Music, Books and Entertainment","dur":138,"audio":"audio/a2/workbook/unit-16.mp3","lines":[["","Hello, Riverside Library. How can I help?","",7],["","Hi. I saw an advertisement for your evening entertainment club and I'd like some information.","",11],["","Certainly. We organise different activities each week. Can I take your name first?","",18],["","Yes, I'm Nathan Bell.","",24],["","Could you spell your surname, please?","",27],["","Sure, it's B-E-L-L.","",30],["","Thank you. What kind of entertainment are you most interested in?","",34],["","I love films and music, but I'm especially interested in books. I read almost every evening.","",39],["","Then you might enjoy our reading group. We meet twice a month and discuss a different book each time.","",46],["","That sounds good. Which day do you meet?","",53],["","We used to meet on Tuesdays, but this month the meetings are on Wednesday evenings because the library has another event on Tuesdays.","",56],["","Wednesday is fine. What time does it start?","",64],["","At 7.15. Most people arrive a little earlier and have tea or coffee before the discussion begins.","",68],["","Nice. What book are you reading at the moment?","",75],["","It's an adventure story called The Long Road. It's about two friends travelling through the mountains.","",79],["","The writer is coming to our next meeting.","",85],["","Really? That sounds interesting.","",88],["","Yes. After the discussion, she'll answer questions and talk about how she became a writer.","",91],["","Great. Do I have to buy the book?","",98],["","No. Members can borrow a copy from the library for three weeks. Just show your library card at the front desk.","",101],["","Perfect. Is there a cost to join the group?","",109],["","The reading group itself is free. We sometimes organise cinema trips and members pay for those separately.","",112],["","Do you have any other events this month?","",120],["","Yes, there's a live music evening on the 24th. A local singer will perform in the café. Tickets are £6.","",122],["","I might come to that too.","",132],["","Great! I'll give you the details when you come to the reading group.","",134]]},
{"id":"wb-17","u":17,"book":"Workbook","title":"Interesting people and their lives","dur":118,"audio":"audio/a2/workbook/unit-17.mp3","lines":[["","Welcome to young people doing interesting things. Today we're talking to someone who started his own","",6],["","small business while he was still at school. Thanks for coming. Could you introduce yourself?","",12.7],["","Sure, I'm Daniel Moore.","",19.2],["","Could you spell your surname for our listeners?","",22],["","Yes, it's M-O-O-R-E.","",25.1],["","Thanks, Daniel. Where are you from?","",30],["","I was born in Manchester, but when I was six, my family moved to Bristol.","",32.9],["","I've lived there ever since.","",37.8],["","Tell us about your business. How did it begin?","",39.8],["","I've always enjoyed making things. When I was 16, I started making simple wooden boxes at home.","",43.3],["","At first, they were just presents for family members.","",50.2],["","So when did it become a business?","",53.8],["","A friend asked if she could buy one. Then other people became interested.","",56.6],["","I started selling the boxes online, and after a few months, I was getting several orders each week.","",61],["","Did you make everything at home?","",67.4],["","At first, yes. I worked in our garage because there wasn't enough space in my bedroom.","",70],["","Last year, I rented a small workshop near my house.","",75.8],["","Do you work there alone?","",79.6],["","Not anymore. My cousin works with me three days a week.","",81.8],["","She answers customer messages and takes photos of our products for the website.","",85.8],["","What do you enjoy most about your work?","",90.8],["","I like designing new things. Making the same box again and again can get boring,","",93.8],["","so creating something different is much more exciting.","",99.4],["","And what are your plans for the future?","",103.1],["","I'd like to open a small shop one day. I enjoy selling online,","",106.1],["","but I think it would be nice to meet more of my customers.","",110.3],["","Sounds like a great plan. Thanks for talking to us.","",113.7]]},
{"id":"wb-18","u":18,"book":"Workbook","title":"Festivals, Celebrations and Traditions","dur":132,"audio":"audio/a2/workbook/unit-18.mp3","lines":[["","Hello, Oakfield Community Centre, how can I help?","",5.3],["","Hi, I saw a poster about your spring celebration and I'd like to bring my family.","",11.2],["","Wonderful, it's a traditional event we organise every year. Can I take your name first?","",17.8],["","Yes, I'm Robert Dean.","",24.7],["","Could you spell your surname, please?","",27.6],["","Of course, it's D-E-A-N.","",30.6],["","Thank you. This year's celebration will be on Saturday the 9th.","",35.2],["","Last year we held it on a Sunday, but Saturday is easier for most families.","",40],["","Great. What time should we arrive?","",45.6],["","The doors open at 10, but the first activity begins at 10.45.","",48.6],["","It's a traditional dance performed by children from the local school.","",53.8],["","My daughter will enjoy that. What else is happening?","",58.3],["","After the dance, there'll be music and several family games.","",62.3],["","At lunchtime, local families will serve traditional food.","",66.5],["","What kind of food?","",70.9],["","There'll be rice dishes, meat and vegetables.","",72.7],["","We'll also have a special sweet cake that people usually make for this celebration.","",76.3],["","Sounds delicious. Can children take part in the activities?","",82.2],["","Absolutely. One popular activity is making traditional decorations from paper.","",87],["","Children can take them home afterwards.","",93],["","Nice. Is there anything we should bring?","",96.1],["","If the weather is good, some activities will be outside, so bring a hat for the children.","",99.4],["","It can get quite sunny in the afternoon.","",105.4],["","OK. Do we need to buy tickets?","",108.6],["","Entry is free for children under 12. Adult tickets are £7 and that includes all the activities.","",111.5],["","Excellent. Can we buy tickets when we arrive?","",119.6],["","Yes, but the event is usually busy, so coming early is a good idea.","",123.3],["","We will. Thanks for your help.","",129.1]]},
{"id":"wb-19","u":19,"book":"Workbook","title":"Childhood and Memories","dur":129,"audio":"audio/a2/workbook/unit-19.mp3","lines":[["","Welcome back to Growing Up. Today, we're asking people about things they remember from childhood.","",5.4],["","Could you introduce yourself? Of course. I'm Michael Green.","",12.4],["","Could you spell your surname, please? Sure. It's G-R-E-E-N.","",17.8],["","Thanks, Michael. Where did you live when you were a child?","",25.9],["","I was born in a city, but when I was five, we moved to a small village in the countryside.","",30.2],["","My parents wanted somewhere quieter for us to grow up.","",36],["","What did you like about living there? I loved being outdoors. There was a field","",39.8],["","behind our house, and my friends and I spent hours there. We played football,","",45.3],["","climbed trees, and sometimes had picnics. What was school like?","",50.1],["","It was quite small. I started there when I was six, and there were only about 20 children in my class.","",55.3],["","I was nervous at first, but I soon made friends. Did you have a favourite teacher?","",62.2],["","Yes, Mr Thomas. He taught science. His lessons were always interesting,","",68.6],["","because we did simple experiments instead of only reading from books.","",73.6],["","What did you usually do when you got home from school?","",78.2],["","My mum usually gave me something to eat first. Then I did my homework. After that,","",81.9],["","I often rode my bike to my best friend's house. Do you remember your birthdays?","",87.4],["","Definitely. My parents usually organised a small party at home. On my tenth birthday,","",93.4],["","I got a camera. I took pictures of absolutely everything for months.","",99.1],["","What is your favourite childhood memory? Probably our summer holidays. We went to","",104.9],["","the same place every year and stayed in a small house near a forest.","",110.6],["","My brother and I loved exploring it with our dad.","",115],["","Do you still have any of those old photographs?","",118.6],["","Yes, I keep them in a box at my parents' house. Looking at them always brings back good memories.","",122]]},
{"id":"wb-20","u":20,"book":"Workbook","title":"Everyday problems and solutions","dur":125,"audio":"audio/a2/workbook/unit-20.mp3","lines":[["","Good afternoon. City Bus lost property office. How can I help?","",5.5],["","Hi, I think I left my bag on a bus this morning.","",10.6],["","Okay, I'll take some details and see if anyone has found it. Can I have your name first?","",14.6],["","Yes, I'm James Cook.","",21.7],["","Could you spell your surname, please?","",24.5],["","Of course. It's C-O-O-K.","",26.5],["","Thank you. Do you remember which bus you were on?","",31.5],["","Yes, it was the number 27. I usually take the 19, but that bus was late this morning, so I took a different one.","",35.5],["","I see. What time did you get off the bus?","",44.5],["","At about 8.20. I didn't notice the bag was missing until I arrived at work about 15 minutes later.","",48.5],["","Can you describe the bag?","",55.5],["","It's a small black backpack.","",57.5],["","I also have a blue one at home, but the one I lost is definitely black.","",60.5],["","And what was inside it?","",65.5],["","My lunch, a notebook and a pair of glasses.","",67.5],["","Luckily I had my phone and wallet in my coat pocket.","",71.5],["","That's good. Did the bag have your name on it?","",74.5],["","No, but there's a small green keyring on the front.","",78.5],["","It looks like a football.","",82.5],["","All right. We haven't received a black backpack yet, but drivers usually bring lost items here after their shift.","",84.5],["","The bus you took should return to the station at 2.30 this afternoon.","",92.5],["","So, should I call again later?","",97.5],["","Yes. Try us after 3. If we find the bag, you can collect it from the lost property office next to the ticket desk.","",100.5],["","OK. What time do you close?","",108.5],["","At six today. If you can't come before then, we can keep the bag here for you.","",111.5],["","Great. Thanks. I was worried I'd lost it completely.","",117.5],["","Hopefully it will turn up this afternoon.","",121.5]]},
{"id":"wb-21","u":21,"book":"Workbook","title":"Helping people and community life","dur":140,"audio":"audio/a2/workbook/unit-21.mp3","lines":[["","Hello, Eastside Community Kitchen. How can I help?","",6.1],["","Hi, my friend volunteers with you and she said you need more people to help.","",10.2],["","We do. Thanks for calling. Can I take your name first?","",16.2],["","Yes, I'm Matthew Ford.","",21.4],["","Could you spell your surname, please?","",24.2],["","Sure, it's F-O-R-D.","",27.1],["","Thank you. Have you done any volunteer work before?","",31.5],["","Yes. Last year I helped at a school event.","",35.8],["","I served drinks and helped clean up afterwards, but I've never worked in a community kitchen.","",39.5],["","That's absolutely fine. We prepare free meals for people who need them.","",45.7],["","New volunteers usually start by preparing vegetables.","",51],["","They wash them, cut them, and get them ready for cooking.","",54.7],["","Great. I cook quite a lot at home, so I'd be comfortable doing that.","",58.5],["","Excellent. We prepare meals on Wednesdays and Fridays.","",63.5],["","Wednesday is already quite busy, so we especially need help on the other day.","",68],["","Friday works well for me.","",73.4],["","Good. We start cooking at five, but volunteers need to arrive by four-forty-five","",75.5],["","so they can wash their hands, put their things away, and get ready.","",81.6],["","No problem. How long would I stay?","",85.6],["","Usually until about eight. We start serving the meals at six-thirty.","",89],["","Do I need to bring any equipment?","",94.5],["","No. We provide everything in the kitchen. Just wear comfortable clothes and closed shoes.","",97],["","Open shoes aren't safe when you're working around hot food.","",103.5],["","Okay. Is there anything else I can help with?","",107.5],["","Sometimes we need people to deliver meals to older residents.","",111.1],["","Volunteers usually go in pairs and travel by car.","",115.5],["","I have a car, so I could do that sometimes.","",119.5],["","That would be very helpful.","",123],["","Before you begin, there's a short training session.","",125],["","It lasts thirty minutes and explains the kitchen's safety rules.","",128.4],["","Great. When's the next one?","",133.2],["","This Thursday at six.","",135.8],["","Perfect. I'll be there.","",138.2]]},
{"id":"wb-22","u":22,"book":"Workbook","title":"Trying something new","dur":138,"audio":"audio/a2/workbook/unit-22.mp3","lines":[["","Hello, Creative Skills Centre. How can I help?","",5.1],["","Hi, I'm looking for a new hobby and a friend told me about your beginner courses.","",9],["","Great! We have several courses for people who want to try something different.","",14.7],["","Can I take your name first?","",19.7],["","Yes, I'm Thomas Riley.","",22.2],["","Could you spell your surname, please?","",25],["","Of course. It's R-I-L-E-Y.","",27.7],["","Thank you. What sort of things are you interested in?","",33],["","I work on a computer all day, so I'd like to do something with my hands.","",37],["","I've thought about painting, but I'm not very good at drawing.","",42.2],["","You don't need to be. We also have cooking, photography and pottery courses.","",46.5],["","I already cook quite a lot at home, and I use my phone for photos.","",52.6],["","Pottery sounds more unusual. I've never tried anything like that.","",57.2],["","Then our beginner course would be perfect. It's a four-week course,","",61.8],["","and you'll learn how to make simple bowls and cups.","",66.2],["","Nice! When are the classes?","",69.8],["","There's a Monday class and a Thursday class.","",72.5],["","Monday starts at 6, but Thursday is a little later.","",75.8],["","Thursday would be better, because I usually work late on Mondays.","",80.1],["","Fine. The Thursday class starts at 6.45 and lasts an hour and a half.","",84.6],["","Do I need to buy any equipment?","",91.2],["","No. We provide all the tools and materials.","",93.7],["","You should bring an old shirt, though, because your clothes may get dirty.","",97.3],["","Good idea. How many people are in each class?","",101.8],["","We allow a maximum of ten, but there are usually about eight.","",105.8],["","That gives the teacher enough time to help everyone.","",110.4],["","And how much is the course?","",114],["","It normally costs £50, but beginners joining this month pay £40 for all four classes.","",116.2],["","Great! Where is the pottery room?","",124.2],["","It's upstairs in room seven, opposite the photography room.","",127],["","Perfect. I'd like to give it a try.","",131.8],["","Excellent. I'll reserve a place for you.","",134.7]]},
{"id":"wb-23","u":23,"book":"Workbook","title":"Interesting places and different cultures","dur":134,"audio":"audio/a2/workbook/unit-23.mp3","lines":[["","Hello. City Exchange Club. How can I help?","",5.9],["","Hi. I saw some information about your cultural evening next week and I'd like to come.","",9.8],["","Great. I can give you all the details. Can I take your name first?","",16],["","Yes. I'm Ben Carter. Could you spell your surname, please?","",21.4],["","Of course. It's C-A-R-T-E-R.","",26.2],["","Thank you. This month our cultural evening is about Mexico.","",32.2],["","Last month we looked at Spain, so we wanted to choose somewhere different this time.","",37.2],["","Nice. I don't know much about Mexico, so it should be interesting.","",42.2],["","The evening begins with a short talk by a student who lived there for a year.","",47.2],["","She'll show photographs of different cities and talk about family life, school and food.","",52.2],["","What time does the talk start?","",59.2],["","The doors open at 6, but the talk begins at 6.30. Try to arrive a little earlier because it can get busy.","",61.2],["","I will. Is there any food to try?","",69.2],["","Yes. After the talk, visitors can try several dishes.","",72.2],["","dishes. One of them is a traditional soup made with vegetables and chicken.","",77.2],["","Great! I enjoy trying new food.","",82.9],["","Later there'll be a short dance lesson. You don't need any experience and everyone is","",86.4],["","welcome to join.","",91.9],["","That sounds fun. What should we wear?","",94],["","Anything comfortable. If you want to join the dancing, comfortable shoes are especially","",97.3],["","important.","",102.3],["","to know. Will there be anything to buy? Yes, there'll be a small market with handmade","",103.9],["","gifts, books and traditional clothes. Some of the students brought the items back from","",110.5],["","their travels. How much is the event? It's £6 for adults. Children under 12 can come","",115.8],["","for free. Perfect. Where is it being held? In the community hall besides Central Library.","",123.4],["","Great, thanks for the information.","",131.4]]},
{"id":"wb-24","u":24,"book":"Workbook","title":"Life in the past and life today","dur":128,"audio":"audio/a2/workbook/unit-24.mp3","lines":[["","Welcome back to Life Changes. Today we're talking to people about how their daily lives are different","",6],["","from when they were young. Could you introduce yourself? Certainly. My name's Robert James.","",12.7],["","Could you spell your surname please? Of course. It's J-A-M-E-S.","",19.9],["","Thanks Robert. Where did you live as a child?","",27.7],["","I grew up on a farm about 10 kilometres from the nearest town.","",31.3],["","It was a quiet place and there weren't many other children living nearby.","",35.6],["","How did you get to school? A school bus picked us up every morning. I had to leave home at 7.15","",40.9],["","because the bus stopped at several villages before reaching the school.","",48.1],["","What was school like then? We didn't have computers of course.","",52.6],["","We wrote everything by hand in our notebooks. If we needed information for homework we usually looked","",57.3],["","in books. What did you do after school? I often helped my parents on the farm. After that I played","",63.4],["","outside with my brother. We had a television but I was only allowed to watch it for about an hour","",71.5],["","each evening. How did your family do its shopping? We drove into town every Saturday. My mother made","",77.4],["","a long list because we needed enough food for the whole week. And how is your life different today?","",84.9],["","Well I live in a city now so everything is much closer. I can walk to several shops and I","",91.7],["","sometimes order food online. Communication is much easier too. Do you use technology a lot?","",98.2],["","Yes. I use my phone every day for messages, maps, news and even paying for things. When I was young","",106],["","I never imagined one small thing could do all of that. Is there anything you miss about the past?","",113.8],["","I miss how peaceful life on the farm was but I think modern life is more convenient.","",121.4]]}
];
